// Load the static exports (C) into the normalised model. Every value taken from the temporary
// fallback (public/fallback/aqdata.json, a copy of the wireframe's data) is flagged in `status`.
import type { EmitKey, Pollutant } from "../types";
import type { Manifest } from "../engine/manifest";
import { CLOUD_TENTHS, EMIT_KEYS, FAMILY_UI, LABEL, LABEL_OVERRIDE, URBAN_APPLIES } from "./catalogue";
import { PUBLIC_SITE } from "../config";
import { GASES, UG_PER_PPB_DEFAULT, ugPerPpbFrom } from "./units";
import type { AppData, BackgroundValue, Controls, Family, PollutantInfo, RoadsInfo, ScenarioInfo, StandardRef, Tech } from "./model";

declare const __AQ_DATA_BASE__: string;

/** Base URL of the data (`export/` folder): build-time default, `?data=` overrides it. */
export function dataBase(): string {
  const q = new URLSearchParams(location.search).get("data");
  let b = q || (typeof __AQ_DATA_BASE__ === "string" ? __AQ_DATA_BASE__ : "../../export/");
  if (!b.endsWith("/")) b += "/";
  return new URL(b, location.href).href;
}

async function getJSON<T>(url: string): Promise<T | null> {
  try {
    const r = await fetch(url, { cache: "no-cache" });
    if (!r.ok) return null;
    return (await r.json()) as T;
  } catch {
    return null;
  }
}

const canon = (s: string) => String(s).toUpperCase().replace(/[._\- ]/g, "");
const toEmit = (k: string): EmitKey | null => {
  const c = canon(k);
  if (c === "NO2" || c === "NOX") return "NOx";
  if (c === "SO2" || c === "CO" || c === "PM25") return c as EmitKey;
  return null;
};

/* eslint-disable @typescript-eslint/no-explicit-any */
type Json = any;

export async function loadData(): Promise<AppData> {
  const base = dataBase();
  const F = base + "fields/";
  const manifest = await getJSON<Manifest>(F + "manifest.json");
  if (!manifest) throw new Error(`Could not load ${F}manifest.json. Check that the export/ folder is served next to the app (see docs/phase3_F_app.md).`);
  const [sourcesJ, bgJ, ctlJ, roadsJ] = await Promise.all([
    getJSON<Json>(F + "sources.json"), getJSON<Json>(F + "backgrounds.json"),
    getJSON<Json>(F + "controls.json"), getJSON<Json>(F + "roads.json"),
  ]);
  const needFallback = !sourcesJ || !bgJ || !ctlJ || !roadsJ;
  const fb: Json = needFallback ? await getJSON<Json>(new URL("fallback/aqdata.json", location.href).href) : null;

  // ---------------------------------------------------------------- scenarios
  const fbScn: Record<string, Json> = Object.fromEntries((fb?.scenarios || []).map((s: Json) => [s.id, s]));
  const tf: Record<string, number> = roadsJ?.scenario_traffic_factor || roadsJ?.hourly_traffic?.scenario_factor || {};
  const order = ["stable_night", "neutral_windy", "convective_deep", "convective_winter", "morning_transition"];
  const ids = Object.keys(manifest.scenarios).sort((a, b) => (order.indexOf(a) + 99 * +(order.indexOf(a) < 0)) - (order.indexOf(b) + 99 * +(order.indexOf(b) < 0)));
  const scenarios: ScenarioInfo[] = ids.map((id) => {
    const s = { ...manifest.scenarios[id] };
    if (LABEL_OVERRIDE[id]) s.label = LABEL_OVERRIDE[id];
    if (PUBLIC_SITE) { delete s.teaching; delete s.artifacts; }   // instructor-only text stays out of the public site
    return {
      ...s,
      trafficFactor: tf[id] ?? fbScn[id]?.traffic_factor ?? 1,
      cloudTenths: CLOUD_TENTHS[id] ?? fbScn[id]?.ccvr_tenths ?? null,
      urbanApplies: URBAN_APPLIES[id] ?? fbScn[id]?.urban_applies ?? s.zi_effective_m !== s.zi_m,
    };
  });
  const scenarioById = Object.fromEntries(scenarios.map((s) => [s.id, s]));

  // ---------------------------------------------------------------- families (palette)
  const families: Family[] = [];
  const familyOfSource: Record<string, string> = {};
  for (const ui of FAMILY_UI) {
    let options: Family["options"] = [];
    let label = ui.name, controlLabel: string | null = null, defaultOpt = ui.defaultOpt;
    const fj = sourcesJ?.families?.[ui.key];
    if (fj) {
      label = fj.label || label;
      controlLabel = fj.control_label || null;
      defaultOpt = fj.default || defaultOpt;
      options = fj.options.map((o: Json) => {
        const p = manifest.sources[o.source_id]?.params || {};
        const h = o.value ?? p.stack_height ?? p.release_height ?? 0;
        return { id: o.source_id, h, label: o.value != null ? `${o.value} m` : o.label };
      });
    } else {
      options = Object.values(manifest.sources).filter((s) => s.category === ui.key).map((s) => ({
        id: s.id, h: s.params.stack_height ?? s.params.release_height ?? 0, label: s.params.stack_height ? `${s.params.stack_height} m` : s.label,
      })).sort((a, b) => a.h - b.h);
      if (ui.kind === "stack") controlLabel = "Stack height";
    }
    options = options.filter((o) => manifest.fields.some((f) => f.source_id === o.id));
    if (!options.length) continue;
    if (!options.some((o) => o.id === defaultOpt)) defaultOpt = options[Math.floor(options.length / 2)].id;
    families.push({ ...ui, label, controlLabel, options, defaultOpt });
    for (const o of options) familyOfSource[o.id] = ui.key;
  }

  // ---------------------------------------------------------------- backgrounds and standards
  const backgrounds: AppData["backgrounds"] = {};
  const pollutantInfo: AppData["pollutantInfo"] = {};
  const standards: StandardRef[] = [];
  let generalCaveats: string[] = [];
  if (bgJ) {
    generalCaveats = bgJ.general_caveats || [];
    for (const [k, p] of Object.entries<Json>(bgJ.pollutants || {})) {
      const key = canon(k) as Pollutant;
      pollutantInfo[key] = { label: p.label || LABEL[key], nativeUnits: p.native_units, ugPerNative: p.ug_m3_per_native_unit ?? null,
        caveats: p.caveats || [], note: p.note || null, naaqsText: p.naaqs_text || null } as PollutantInfo;
      for (const n of p.naaqs || []) {
        if (n.level_ug_m3 == null) continue;
        standards.push(makeStandard(key, n.level, n.units, n.level_ug_m3, n.averaging, n.form || ""));
      }
    }
    for (const [sid, per] of Object.entries<Json>(bgJ.scenarios || {})) {
      backgrounds[sid] = {};
      for (const [k, e] of Object.entries<Json>(per)) {
        backgrounds[sid][canon(k) as Pollutant] = { ug: e.value_ug_m3 ?? null, native: e.value_native ?? null, units: e.native_units ?? null,
          monitorClass: e.monitor_class ?? null, method: e.method ?? null, flags: e.flags || [], aqsHour: e.aqs_hour ?? null } as BackgroundValue;
      }
    }
  } else if (fb) {
    for (const [sid, per] of Object.entries<Json>(fb.backgrounds || {})) {
      backgrounds[sid] = {};
      for (const [k, e] of Object.entries<Json>(per)) backgrounds[sid][canon(k) as Pollutant] = {
        ug: e.value_ug_m3 ?? null, native: e.value ?? null, units: e.units ?? null, monitorClass: e.monitor_class ?? null,
        method: e.method ?? null, flags: e.monitor_class && e.monitor_class !== "A" ? ["urban_monitor"] : [] };
    }
    for (const [k, p] of Object.entries<Json>(fb.pollutants || {})) {
      const key = canon(k) as Pollutant;
      pollutantInfo[key] = { label: LABEL[key], nativeUnits: p.aqs_units, ugPerNative: p.ug_m3_per_aqs_unit, caveats: [], note: p.note, naaqsText: p.naaqs_reference };
    }
    const C = { SO2: 2.6203, NO2: 1.8816, CO: 1145.6033 };
    standards.push(
      makeStandard("SO2", 75, "ppb", 75 * C.SO2, "1-hour", "99th percentile of daily maximum 1-hour values, averaged over 3 years"),
      makeStandard("NO2", 100, "ppb", 100 * C.NO2, "1-hour", "98th percentile of daily maximum 1-hour values, averaged over 3 years"),
      makeStandard("NO2", 53, "ppb", 53 * C.NO2, "annual", "annual mean"),
      makeStandard("CO", 35, "ppm", 35 * C.CO, "1-hour", "not to be exceeded more than once per year"),
      makeStandard("CO", 9, "ppm", 9 * C.CO, "8-hour", "not to be exceeded more than once per year"),
      makeStandard("PM25", 35, "ug/m3", 35, "24-hour", "98th percentile, averaged over 3 years"),
      makeStandard("PM25", 9, "ug/m3", 9, "annual", "annual mean, averaged over 3 years (2024 revision)"),
    );
  }

  // ---------------------------------------------------------------- display conversion (gases in ppb)
  const ugPerPpb: AppData["ugPerPpb"] = {};
  for (const g of GASES) {
    const i = pollutantInfo[g];
    ugPerPpb[g] = ugPerPpbFrom(i?.ugPerNative, i?.nativeUnits) ?? UG_PER_PPB_DEFAULT[g];
  }

  // ---------------------------------------------------------------- controls
  const controls = ctlJ ? parseControls(ctlJ) : fallbackControls();

  // ---------------------------------------------------------------- roads
  let roads: RoadsInfo;
  if (roadsJ) {
    const hourly: RoadsInfo["hourly"] = {};
    for (const [t, tt] of Object.entries<Json>(roadsJ.tier_totals || {})) hourly[t] = tt.hourly_g_s || {};
    roads = {
      attribution: roadsJ.attribution || "Road geometry (c) OpenStreetMap contributors, ODbL 1.0",
      roads: (roadsJ.roads || []).filter((r: Json) => r.tier <= 2).map((r: Json) => ({ id: r.id, name: r.name, ref: r.ref, tier: r.tier,
        line: r.centreline, n_segments: r.n_segments, length_m: r.length_m })),
      tierLabels: roadsJ.tier_labels || { 1: "Motorways", 2: "Trunk roads" },
      hourly, trafficFactor: tf,
      trafficDataNote: "Traffic volumes: PennDOT RMS (via PASDA) and NJDOT AADT.",
      efBasis: roadsJ.emission_factors?.basis || "",
    };
  } else {
    roads = {
      attribution: fb?.roads_meta?.attribution || "Road geometry (c) OpenStreetMap contributors, ODbL 1.0",
      roads: (fb?.roads || []).map((r: Json) => ({ id: r.id, name: r.name, ref: r.ref, tier: r.tier, line: r.line, n_segments: r.n_segments, length_m: r.length_m })),
      tierLabels: { 1: "Motorways", 2: "Trunk roads" }, hourly: {}, trafficFactor: Object.fromEntries(scenarios.map((s) => [s.id, s.trafficFactor])),
      trafficDataNote: "Traffic volumes: PennDOT RMS (via PASDA) and NJDOT AADT.", efBasis: "",
    };
  }

  const rb = manifest.road_baselines && (manifest.road_baselines.maps || manifest.road_baselines.entries)?.length ? manifest.road_baselines : null;
  const missing: string[] = [];
  if (!sourcesJ) missing.push("export/fields/sources.json");
  if (!bgJ) missing.push("export/fields/backgrounds.json");
  if (!ctlJ) missing.push("export/fields/controls.json");
  if (!roadsJ) missing.push("export/fields/roads.json");
  if (!rb) missing.push("road_baselines in export/fields/manifest.json (export/fields/roads/*.bin)");
  return {
    base, manifest, scenarios, scenarioById, families, familyOfSource, backgrounds, pollutantInfo, ugPerPpb, generalCaveats, standards, controls, roads,
    roadBaselines: rb,
    status: {
      sourcesJson: !!sourcesJ, backgroundsJson: !!bgJ, controlsJson: !!ctlJ, roadsJson: !!roadsJ, roadBaselines: !!rb,
      roadVertical: !!rb && !!(rb.vertical as unknown) && (rb.maps || []).some((m) => !!(m as Json).vertical), ozone: false, missing,
    },
  };
}

function makeStandard(pol: Pollutant, level: number, units: string, ug: number, avg: string, form: string): StandardRef {
  const u = units === "ug/m3" ? "µg/m³" : units;
  const hours = /(\d+)-hour/.exec(avg);
  const why = avg === "1-hour"
    ? `Same averaging time as the map, but the standard's form (${form}) is a statistic over many days and years.`
    : avg === "annual" ? "Annual mean: it needs every hour of a year; one hour says little about it."
      : `${avg} average: the other ${hours ? +hours[1] - 1 : "several"} hours are not modelled.`;
  return { id: `${pol}_${avg.replace(/[^a-z0-9]/gi, "")}`, pol, name: `${LABEL[pol]} ${avg} NAAQS`, level: `${level} ${u}`, ug, levelNum: level, levelUnits: units, avg, sameAveraging: avg === "1-hour", form, why };
}

function parseControls(j: Json): Controls {
  const technologies = { SO2: [], NOx: [], CO: [], PM25: [] } as Record<EmitKey, Tech[]>;
  for (const [k, list] of Object.entries<Json>(j.technologies || {})) {
    const ek = toEmit(k);
    if (!ek) continue;
    technologies[ek] = (list as Json[]).map((t) => ({
      id: t.id, name: t.name,
      efficiency: typeof t.efficiency === "number" ? t.efficiency : t.efficiency?.typical ?? 0,
      range: Array.isArray(t.efficiency?.range) ? t.efficiency.range : null,
      appliesTo: t.applies_to || [],
      capital: Object.fromEntries(Object.entries<Json>(t.capital || {}).map(([fam, c]) => [fam, { basis: c.basis, usdPerUnit: c.usd_per_unit, refSize: c.ref_size, exponent: c.exponent ?? 1 }])),
      lifeYears: t.life_years ?? null,
      crf: t.crf ?? crf(j.annualisation?.interest_rate ?? 0.075, t.life_years ?? 20),
      fixedOmFraction: t.fixed_om_fraction ?? 0,
      variableUsdPerTon: typeof t.variable_usd_per_ton === "number" ? t.variable_usd_per_ton : t.variable_usd_per_ton?.typical ?? 0,
      note: t.note || "", references: t.references || [],
    }));
  }
  const notOffered = { SO2: {}, NOx: {}, CO: {}, PM25: {} } as Controls["notOffered"];
  for (const [k, v] of Object.entries<Json>(j.not_offered || {})) { const ek = toEmit(k); if (ek) notOffered[ek] = v; }
  const capacity: Controls["capacity"] = {};
  let basisNotes: Record<string, string> = {};
  for (const [k, v] of Object.entries<Json>(j.capacity || {})) {
    if (k === "basis_notes") basisNotes = v; else capacity[k] = v;
  }
  return { approximate: j.approximate !== false, costYear: j.cost_year ?? null, interestRate: j.annualisation?.interest_rate ?? null,
    capacity, basisNotes, technologies, notOffered, references: j.references || {}, fallback: false };
}

export function crf(i: number, n: number): number {
  return i > 0 ? (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1) : 1 / n;
}

/** TEMPORARY FALLBACK: the wireframe's technologies with a variable cost only (no capital). */
function fallbackControls(): Controls {
  const S = ["power_plant_stack", "industrial_stack"];
  const T = (id: string, name: string, eff: number, usd: number, applies = S, note = ""): Tech => ({ id, name, efficiency: eff, range: null, appliesTo: applies,
    capital: {}, lifeYears: null, crf: null, fixedOmFraction: 0, variableUsdPerTon: usd, note, references: [] });
  const technologies: Record<EmitKey, Tech[]> = {
    SO2: [T("dsi", "Dry sorbent injection (DSI)", 0.5, 4000), T("sda", "Spray dryer absorber (dry FGD)", 0.9, 2500), T("wfgd", "Wet limestone FGD", 0.95, 2000)],
    NOx: [T("lnb", "Low-NOx burners", 0.4, 1000), T("sncr", "SNCR (urea or ammonia, no catalyst)", 0.35, 3000), T("scr", "SCR (catalyst)", 0.85, 5000)],
    PM25: [T("cyc", "Cyclone", 0.3, 300), T("esp", "Electrostatic precipitator (ESP)", 0.95, 1500), T("bag", "Fabric filter (baghouse)", 0.99, 2000),
      T("water", "Water spray or dust suppressant", 0.5, 800, ["area"]), T("fence", "Wind fence plus paving", 0.7, 2500, ["area"]),
      T("encl", "Enclosure vented to a baghouse", 0.95, 4000, ["volume"])],
    CO: [T("gcp", "Combustion tuning", 0.3, 500), T("oxcat", "Oxidation catalyst", 0.8, 1500)],
  };
  void EMIT_KEYS;
  return { approximate: true, costYear: null, interestRate: null, capacity: {}, basisNotes: {}, technologies,
    notOffered: { SO2: {}, NOx: {}, CO: {}, PM25: {} }, references: {}, fallback: true };
}
