// Bootstrap: load the exports, build the app, apply a shared configuration from the link, bind
// the top bar (share, save, open), and start prefetching the current hour's fields.
import { loadData } from "./data/load";
import { App } from "./ui/app";
import { copyText } from "./ui/about";
import { decodeConfig, type SavedConfig } from "./state/state";

async function main() {
  let D;
  try {
    D = await loadData();
  } catch (e) {
    document.getElementById("screen-sandbox")!.innerHTML = `<div class="banner red" style="margin:20px"><b>Data not found.</b><span>${(e as Error).message}</span></div>`;
    return;
  }
  const app = new App(D);
  const P = new URLSearchParams(location.search);
  app.setInstructor(P.get("instructor") === "1");
  app.panels.bind();
  app.bindMap();

  document.querySelectorAll<HTMLButtonElement>("#tabs button").forEach((b) => b.onclick = () => app.setScreen(b.dataset.screen as "sandbox"));
  document.getElementById("shareBtn")!.onclick = async () => {
    const url = await app.shareLink();
    const ok = await copyText(url);
    app.toast(ok ? "Link copied to the clipboard. It also stays in the address bar." : "The link is in the address bar; copy it from there.");
  };
  document.getElementById("saveBtn")!.onclick = () => { app.saveFile(); app.toast("Configuration saved as a JSON file."); };
  const input = document.getElementById("loadInput") as HTMLInputElement;
  document.getElementById("loadBtn")!.onclick = () => input.click();
  input.onchange = async () => {
    const f = input.files?.[0];
    if (!f) return;
    try { app.loadConfig(JSON.parse(await f.text()) as SavedConfig, `"${f.name}"`); }
    catch (e) { app.toast(`Could not open ${f.name}: ${(e as Error).message}`); }
    input.value = "";
  };
  window.addEventListener("hashchange", () => { app.loadFromHash(); });
  let rz = 0;
  window.addEventListener("resize", () => { cancelAnimationFrame(rz); rz = requestAnimationFrame(() => { if (app.S.screen === "sandbox") app.layout(); }); });

  const fromLink = await app.loadFromHash();
  if (!fromLink) {
    const sc = P.get("screen");
    app.setScreen(sc === "about" || sc === "linearity" ? sc : "sandbox");
  }
  app.prefetchHours();
  (window as unknown as { __aqDecode: typeof decodeConfig }).__aqDecode = decodeConfig;
}

main();
