// Display units. The engine works in µg/m³ throughout; gases (SO2, NO2, CO, O3) are converted to
// ppb for display only, with A's factors from backgrounds.json at 25 °C and 1 atm. PM2.5 stays in
// µg/m³. The NO2 map carries emitted NOx as a tracer counted as NO2, so it converts with the NO2
// factor.
import type { Pollutant } from "../types";

export type DisplayUnits = "ppb" | "ug";

export const GASES: Pollutant[] = ["SO2", "NO2", "CO", "O3"];

/** µg/m³ per ppb used when backgrounds.json gives no factor (A's values, 25 °C, 1 atm). */
export const UG_PER_PPB_DEFAULT: Record<string, number> = { SO2: 2.6203, NO2: 1.8816, CO: 1.1456033, O3: 1.9631 };

/** µg/m³ per ppb from a factor given per native unit (ppb or ppm). */
export function ugPerPpbFrom(factorPerNative: number | null | undefined, nativeUnits: string | null | undefined): number | null {
  if (factorPerNative == null || !(factorPerNative > 0)) return null;
  const u = String(nativeUnits ?? "").toLowerCase().replace(/\s/g, "");
  if (u === "ppb") return factorPerNative;
  if (u === "ppm") return factorPerNative / 1000;
  return null;
}

export function isGas(p: Pollutant): boolean { return GASES.includes(p); }

/** Convert a µg/m³ value for display. */
export function toDisplay(ug: number, pol: Pollutant, units: DisplayUnits, ugPerPpb: Partial<Record<Pollutant, number>>): { v: number; u: string } {
  const f = ugPerPpb[pol];
  if (units === "ppb" && isGas(pol) && f) return { v: ug / f, u: "ppb" };
  return { v: ug, u: "µg/m³" };
}

/** Lower bound of the fixed colour scale, in display units (round ppb for gases). */
export const SCALE_FLOOR: Record<string, { value: number; unit: "ppb" | "ug" }> = {
  SO2: { value: 0.5, unit: "ppb" },
  NO2: { value: 1, unit: "ppb" },
  CO: { value: 100, unit: "ppb" },
  PM25: { value: 1, unit: "ug" },
};

/** The same lower bound in µg/m³ (what the painter compares against). */
export function scaleFloorUg(pol: Pollutant, ugPerPpb: Partial<Record<Pollutant, number>>): number {
  const s = SCALE_FLOOR[pol] ?? { value: 1, unit: "ug" };
  return s.unit === "ppb" ? s.value * (ugPerPpb[pol] ?? UG_PER_PPB_DEFAULT[pol] ?? 1) : s.value;
}

/**
 * Colour rule of the map (Phase 4 review, 2026-10-28). Returns the ramp index for a cell, or -1 for
 * uncoloured. Total view: a cell is coloured, by its total, when plumes and roads add at least the
 * scale's lower bound; otherwise it shows the background alone and stays uncoloured. Increment
 * view: the increment is coloured when it reaches the lower bound.
 */
export function cellColourIndex(increment: number, background: number, show: "total" | "increment", breaks: readonly number[]): number {
  const lo = breaks[0];
  if (!(increment >= lo)) return -1;
  const v = show === "total" ? background + increment : increment;
  const step = Math.log10(breaks[1]) - Math.log10(lo);
  return Math.min(breaks.length - 1, Math.max(0, Math.floor((Math.log10(v) - Math.log10(lo)) / step + 1e-9)));
}
