// Sandbox panels (context bar, palette, placed list, roads, this hour, selected source, probe,
// summary, legends), the weather-hour and reference-level pickers, and the model-limit pop-ups.
import { CONTROL_KEY, DOMAIN, EMIT_KEYS, LABEL, LIMITS, NEUTRAL_DESC, POL_NOTES, RAMP, SCALE_DECADES, SCN_LIMITS, T_PER_YR_PER_G_S, rampBreaks } from "../data/catalogue";
import { addCosts, NO_COST, techCost } from "../data/costs";
import { RoadMaps, cellValue, verticalValue } from "../data/roadmaps";
import type { PlacedSource } from "../state/state";
import type { EmitKey, Pollutant } from "../types";
import type { App } from "./app";
import { esc, fmt, fmtUsd, pad2, relCityHall } from "./format";

const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;

export class Panels {
  private probeData: { key: string; parts: Map<number, number> } | null = null;
  private probeSeq = 0;
  private vertAsked = new Set<string>();
  constructor(private app: App) {}

  // ------------------------------------------------------------------ static bindings (once)
  bind() {
    const app = this.app, S = app.S;
    document.querySelectorAll<HTMLButtonElement>("#pollutantSeg button").forEach((b) => b.onclick = () => app.setPollutant(b.dataset.pol as Pollutant));
    document.querySelectorAll<HTMLButtonElement>("#unitSeg button").forEach((b) => b.onclick = () => { S.units = b.dataset.unit === "ug" ? "ug" : "ppb"; app.refresh(); });
    document.querySelectorAll<HTMLButtonElement>("#modeSeg button").forEach((b) => b.onclick = () => app.setMode(b.dataset.mode as "select" | "probe"));
    document.querySelectorAll<HTMLInputElement>("#layerToggles input").forEach((cb) => cb.onchange = () => { (S.layers as Record<string, boolean>)[cb.dataset.layer!] = cb.checked; app.refresh({ keepControls: true }); });
    $("limitsBtn").onclick = () => { S.layers.limits = !S.layers.limits; app.refresh({ keepControls: true }); };
    $<HTMLInputElement>("tier1").onchange = (e) => { S.roads.tier1 = (e.target as HTMLInputElement).checked; app.refresh({ keepControls: true }); };
    $<HTMLInputElement>("tier2").onchange = (e) => { S.roads.tier2 = (e.target as HTMLInputElement).checked; app.refresh({ keepControls: true }); };
    $<HTMLInputElement>("trafficScale").oninput = (e) => { S.roads.trafficScale = +(e.target as HTMLInputElement).value / 100; app.refresh({ keepControls: true }); };
    $("scenarioChip").onclick = () => this.openModal("scenarioModal");
    $("metChange").onclick = () => this.openModal("scenarioModal");
    $("standardChip").onclick = () => this.openModal("standardModal");
    $<HTMLInputElement>("rotateToggle").onchange = (e) => { S.windFromDeg = (e.target as HTMLInputElement).checked ? app.observedWd() : null; app.refresh(); };
    $<HTMLInputElement>("rotateSlider").oninput = (e) => { S.windFromDeg = +(e.target as HTMLInputElement).value; this.renderMet(); };
    $<HTMLInputElement>("rotateSlider").onchange = (e) => { S.windFromDeg = +(e.target as HTMLInputElement).value; app.refresh(); };
    document.querySelectorAll<HTMLButtonElement>("#zSeg button").forEach((b) => b.onclick = () => { if (S.section) S.section.zTop = +b.dataset.ztop!; this.renderModeBits(); app.section.update(false); });
    $("sectionExpand").onclick = () => { S.expanded = !S.expanded; app.layout(); };
    document.querySelectorAll<HTMLElement>("[data-close]").forEach((b) => b.onclick = () => this.closeModals());
    document.querySelectorAll<HTMLElement>(".modal").forEach((m) => m.addEventListener("click", (e) => { if (e.target === m) this.closeModals(); }));
    document.addEventListener("click", (e) => { const p = $("limitPop"); if (!p.contains(e.target as Node) && !(e.target as HTMLElement).closest("[data-lim]")) p.classList.add("hidden"); });
    document.addEventListener("keydown", (e) => {
      if (e.key !== "Escape") return;
      if (S.mode === "place") app.setMode("select");
      this.closeModals(); $("limitPop").classList.add("hidden");
    });
  }

  renderAll(keepControls = false) {
    this.renderContext(); this.renderPalette(); this.renderPlaced(); this.renderRoads(); this.renderMet();
    if (keepControls && this.controlsFor === this.controlsKey()) this.updateControlsNumbers(); else this.renderControls();
    this.renderProbe(); this.renderSummary(); this.renderLegend(); this.renderLimitsLegend(); this.renderModeBits(); this.renderMapMsg();
  }

  renderModeBits() {
    const S = this.app.S;
    document.querySelectorAll<HTMLButtonElement>("#modeSeg button").forEach((b) => { const on = b.dataset.mode === S.mode; b.classList.toggle("active", on); b.setAttribute("aria-checked", String(on)); });
    document.querySelectorAll<HTMLInputElement>("#layerToggles input").forEach((cb) => cb.checked = (S.layers as Record<string, boolean>)[cb.dataset.layer!]);
    $("limitsBtn").setAttribute("aria-pressed", String(S.layers.limits));
    document.querySelectorAll<HTMLButtonElement>("#zSeg button").forEach((b) => { const on = +b.dataset.ztop! === (S.section?.zTop ?? 2500); b.classList.toggle("active", on); b.setAttribute("aria-checked", String(on)); });
    const ph = $("placeHint");
    ph.classList.toggle("hidden", S.mode !== "place");
    if (S.mode === "place" && S.placeFamily) {
      ph.innerHTML = `Placing: <b>${esc(this.app.family(S.placeFamily).name)}</b>. Click a free 500 m cell, or focus the map and use the arrow keys and Enter. <button class="linkbtn" id="placeCancel">Cancel</button> (Esc)`;
      $("placeCancel").onclick = () => this.app.setMode("select");
    }
    this.renderPalette();
  }

  renderMapMsg() {
    const S = this.app.S, el = $("mapMsg");
    if (S.pollutant === "O3") {
      el.innerHTML = `No ozone map: the sandbox adds single-source fields, and ozone is formed by chemistry rather than emitted.<br><button class="btn" id="goLin2" style="margin-top:6px">Open the Linearity edge module</button>`;
      el.classList.remove("hidden");
      $("goLin2").onclick = () => this.app.setScreen("linearity");
    } else el.classList.add("hidden");
  }

  // ------------------------------------------------------------------ context bar
  renderContext() {
    const app = this.app, S = app.S, s = app.scenario();
    $("scenarioChipText").textContent = `${s.label} · wind ${Math.round(app.wd())}° ${s.ws_m_s.toFixed(1)} m/s · L ${fmt(s.L_m)} m · zi ${Math.round(s.zi_effective_m)} m`;
    document.querySelectorAll<HTMLButtonElement>("#pollutantSeg button").forEach((b) => { const on = b.dataset.pol === S.pollutant; b.classList.toggle("active", on); b.setAttribute("aria-checked", String(on)); });
    document.querySelectorAll<HTMLButtonElement>("#unitSeg button").forEach((b) => { const on = b.dataset.unit === S.units; b.classList.toggle("active", on); b.setAttribute("aria-checked", String(on)); });
    const st = app.standard();
    $("standardChipText").textContent = st ? `${st.name} (${app.levelShown(st)})` : "None";
    const n = POL_NOTES[S.pollutant], ban = $("polBanner");
    ban.className = "banner " + n.level;
    ban.innerHTML = `<b>${esc(n.lead)}</b><span>${esc(n.text)}</span>${S.pollutant === "O3" ? '<button class="btn" id="goLin">Open the Linearity edge module</button>' : ""}`;
    if (S.pollutant === "O3") $("goLin").onclick = () => app.setScreen("linearity");
    const db = $("dataBanner"), miss = app.D.status.missing;
    db.classList.toggle("hidden", !miss.length);
    if (miss.length) db.innerHTML = `<b>Fallback data in use.</b><span>Missing: ${miss.map(esc).join("; ")}. Values for these come from the wireframe's copy of the configs and are marked approximate.</span>`;
  }

  // ------------------------------------------------------------------ left column
  renderPalette() {
    const app = this.app, S = app.S, full = S.sources.length >= DOMAIN.maxSources;
    const el = $("palette");
    el.innerHTML = app.D.families.map((f) => `<button data-fam="${f.key}" class="${S.placeFamily === f.key ? "active" : ""}" aria-pressed="${S.placeFamily === f.key}" ${full ? 'aria-disabled="true"' : ""} title="${esc(f.blurb)}">
      <span class="ico ${f.ico}" aria-hidden="true"></span><span class="pname">${esc(f.name)}</span><span class="psub">${esc(f.sub)}</span></button>`).join("");
    el.querySelectorAll<HTMLButtonElement>("button").forEach((b) => b.onclick = () => {
      if (S.sources.length >= DOMAIN.maxSources) { app.flash(`At most ${DOMAIN.maxSources} sources can be placed (a limit that keeps the map responsive). Remove one first.`); return; }
      if (S.placeFamily === b.dataset.fam) app.setMode("select"); else { app.setMode("place", b.dataset.fam!); (document.getElementById("mapCanvas") as HTMLCanvasElement).focus({ preventScroll: true }); }
    });
    $("countText").textContent = `${S.sources.length} of ${DOMAIN.maxSources} placed.`;
  }

  renderPlaced() {
    const app = this.app, S = app.S, ek = app.emitKey();
    $("placedEmpty").classList.toggle("hidden", S.sources.length > 0);
    $("placedList").innerHTML = S.sources.map((s) => {
      const f = app.family(s.family), o = f.options.find((q) => q.id === s.sourceId);
      const r = S.pollutant === "O3" ? "" : `${fmt(app.effRate(s, ek))} g/s ${LABEL[ek]}`;
      return `<li><button data-tag="${s.tag}" class="${S.selected === s.tag ? "sel" : ""}" aria-pressed="${S.selected === s.tag}"><span class="tag">S${s.tag}</span>${esc(f.name)}${f.kind === "stack" && o ? ", " + o.h + " m" : ""}<span class="meta">${r}</span></button></li>`;
    }).join("");
    $("placedList").querySelectorAll<HTMLButtonElement>("button").forEach((b) => b.onclick = () => { S.selected = +b.dataset.tag!; app.refresh(); });
  }

  renderRoads() {
    const app = this.app, S = app.S, s = app.scenario(), R = app.D.roads;
    for (const t of [1, 2]) {
      const rs = R.roads.filter((r) => r.tier === t);
      $(`tier${t}n`).textContent = `(${rs.length} roads, ${rs.reduce((a, r) => a + r.n_segments, 0)} segments)`;
    }
    $<HTMLInputElement>("tier1").checked = S.roads.tier1; $<HTMLInputElement>("tier2").checked = S.roads.tier2;
    $<HTMLInputElement>("trafficScale").value = String(Math.round(S.roads.trafficScale * 100));
    $("trafficOut").textContent = `${Math.round(S.roads.trafficScale * 100)} %`;
    const g = (pol: string) => app.tiersOn().reduce((a, t) => a + (R.hourly[String(t)]?.[s.id]?.[pol] ?? 0), 0) * S.roads.trafficScale;
    let msg = `This hour (${pad2(s.hour - 1)}:00–${pad2(s.hour)}:00 LST) traffic is ${Math.round(s.trafficFactor * 100)} % of the daily mean. At the scale chosen, the roads shown emit ${fmt(g("NOx"))} g/s NOx, ${fmt(g("CO"))} g/s CO and ${fmt(g("PM25"))} g/s PM₂.₅.`;
    if (S.pollutant === "SO2") msg += " Roads add no SO₂ here (the road inventory has no SO₂ factor; ultra-low-sulfur fuel makes it small).";
    if (app.rotated()) msg += " The road baseline is hidden while the wind is rotated.";
    if (!app.roadMaps.available) msg += " Road concentration maps are not available in this data export; roads are drawn as lines only.";
    $("trafficHint").textContent = msg;
  }

  renderMet() {
    const app = this.app, S = app.S, s = app.scenario();
    const stab = s.L_m > 1000 ? "near-neutral (L > 0, so AERMOD uses its stable formulation)" : s.L_m > 0 ? "stable" : "convective (unstable)";
    const bg = S.pollutant === "O3" ? app.D.backgrounds[s.id]?.O3 : app.D.backgrounds[s.id]?.[S.pollutant];
    $("metCard").innerHTML = `
      <dt>Hour</dt><dd>${esc(s.date)}, ${pad2(s.hour - 1)}–${pad2(s.hour)} LST</dd>
      <dt>Wind</dt><dd>from ${Math.round(s.wd_deg)}° at ${s.ws_m_s.toFixed(1)} m/s</dd>
      <dt>Stability</dt><dd>${stab}</dd>
      <dt>L</dt><dd>${fmt(s.L_m)} m</dd>
      <dt>Mixing ht</dt><dd>${Math.round(s.zi_m)} m${s.urbanApplies && Math.round(s.zi_effective_m) !== Math.round(s.zi_m) ? `; ${Math.round(s.zi_effective_m)} m used (urban) <button class="i-mark" data-lim="urban_zi" aria-label="About the urban mixing height">i</button>` : ""}</dd>
      <dt>u*, w*</dt><dd>${(s.ustar_m_s ?? 0).toFixed(2)} m/s, ${s.wstar_m_s && s.wstar_m_s > 0 ? s.wstar_m_s.toFixed(2) + " m/s" : "— (not convective)"}</dd>
      <dt>Background</dt><dd>${bg?.ug != null ? esc(app.showC(bg.ug, S.pollutant)) + (bg.flags.includes("urban_monitor") ? ' <span class="flag-dot amber" title="From urban monitors; likely overstates a regional background">!</span>' : "") : "—"}${S.pollutant === "O3" ? " (O₃, for the Linearity module)" : ""}</dd>`;
    this.bindLimits($("metCard"));
    $("rotateWrap").classList.toggle("hidden", !S.settings.allowRotation);
    const rotOn = S.settings.allowRotation && S.windFromDeg != null;
    $<HTMLInputElement>("rotateToggle").checked = rotOn;
    $("rotateBox").classList.toggle("hidden", !rotOn);
    $<HTMLInputElement>("rotateSlider").value = String(Math.round(app.wd()));
    $("rotateOut").textContent = `${Math.round(app.wd())}°${app.rotated() ? ` (observed ${Math.round(s.wd_deg)}°)` : " (observed)"}`;
  }

  // ------------------------------------------------------------------ selected source
  private controlsFor = "";
  private controlsKey() { const s = this.app.selected(); return s ? `${s.tag}|${s.sourceId}|${this.app.S.pollutant}|${s.control[this.app.emitKey()] ?? "none"}|${this.app.S.units}` : "none"; }

  renderControls() {
    const app = this.app, S = app.S, el = $("controlsBody"), s = app.selected();
    this.controlsFor = this.controlsKey();
    if (!s) { el.innerHTML = `<p class="hint">Select a placed source on the map or in the list to change its emission rate, stack height and control technology.</p>`; return; }
    const f = app.family(s.family), ek = app.emitKey(), techs = app.techList(s, ek), t = app.techFor(s, ek);
    const rate = s.rates[ek] || 0;
    const rateLabel = ek === "NOx" ? "NOx emission rate (as NO₂)" : `${LABEL[ek]} emission rate`;
    const notOffered = app.D.controls.notOffered[ek]?.[s.family];
    el.innerHTML = `
      <div class="ctl-head"><span class="tag">S${s.tag}</span><b>${esc(f.name)}</b><button class="btn danger" id="ctlRemove" style="margin-left:auto">Remove</button></div>
      <p class="hint">Cell (${s.cell.i}, ${s.cell.j}) · ${relCityHall(s.x, s.y, DOMAIN.cityHall)}. Drag on the map, or focus the map and use the arrow keys, to move it (snaps to 500 m cells).</p>
      ${f.kind === "stack" ? `<fieldset class="radio-row"><legend>${esc(f.controlLabel || "Stack height")}</legend>${f.options.map((o) => `<label class="${o.id === s.sourceId ? "on" : ""}"><input type="radio" name="sh" value="${o.id}" ${o.id === s.sourceId ? "checked" : ""}>${o.h} m</label>`).join("")}</fieldset>`
        : `<p class="hint">Release height ${f.options[0].h} m${f.footprint ? `; footprint ${f.footprint} m` : ""}. ${f.kind === "area" ? "The square is stored with its edges along and across the wind, so it turns with the wind." : ""}</p>`}
      ${S.pollutant === "O3" ? `<p class="hint">Ozone is not emitted; the rate below is the source's NOx.</p>` : ""}
      <label class="field" for="ctlRateN">${rateLabel} <span class="muted">(0–${fmt(f.rateMax)} g/s)</span></label>
      ${f.kind !== "stack" ? `<p class="hint" id="ctlZero" ${rate === 0 ? "" : "hidden"}>This source emits no ${LABEL[ek]} at the moment. Type a rate (up to ${fmt(f.rateMax)} g/s) to give it some.</p>` : ""}
      <div class="field-row"><input type="number" id="ctlRateN" min="0" max="${f.rateMax}" step="${f.rateStep}" value="${rate}" aria-label="${rateLabel} in g/s"> g/s <span class="muted" id="ctlTpy">(${fmt(rate * T_PER_YR_PER_G_S)} t/yr if continuous)</span></div>
      <input type="range" id="ctlRate" min="0" max="${f.rateMax}" step="${f.rateStep}" value="${rate}" aria-label="${rateLabel} slider">
      <fieldset class="tech"><legend>Control technology for ${LABEL[ek]} <span class="approx">efficiencies and costs approximate</span></legend>
        <label class="${!t ? "on" : ""}"><input type="radio" name="tech" value="none" ${!t ? "checked" : ""}><span>No control</span><span class="eff">0 %</span></label>
        ${techs.map((q) => {
          const c = techCost(q, s.family, s.sourceId, rate, app.D.controls);
          return `<label class="${t && q.id === t.id ? "on" : ""}"><input type="radio" name="tech" value="${q.id}" ${t && q.id === t.id ? "checked" : ""}>
          <span>${esc(q.name)}</span><span class="eff">${Math.round(q.efficiency * 100)} %</span>
          <span class="sub">${q.range ? `Typical ${Math.round(q.range[0] * 100)}–${Math.round(q.range[1] * 100)} %. ` : ""}${c.capitalUsd ? `Capital ${fmtUsd(c.capitalUsd)}; ` : ""}${fmtUsd(q.variableUsdPerTon)}/t variable${c.usdPerTon != null ? `; about ${fmtUsd(c.annualUsd)}/yr here (${fmtUsd(c.usdPerTon)}/t)` : ""}. ${esc(q.note)}</span></label>`;
        }).join("")}
        ${!techs.length ? `<p class="hint">No control option for ${LABEL[ek]} from this source type in this tool.${notOffered ? " " + esc(notOffered) : ""}</p>` : ""}
      </fieldset>
      <dl class="kv" id="ctlKv"></dl>
      <p class="hint" id="ctlGm"></p>
      <table class="mini-table" id="ctlTable"></table>
      <p class="hint">${esc(f.blurb)} Each source keeps its own rates and controls for all four pollutants.</p>
      <div class="lin-nav"><button class="btn" id="ctlAlign">Put the section line along this plume</button></div>`;
    el.querySelectorAll<HTMLInputElement>("input[name=sh]").forEach((r) => r.onchange = () => { s.sourceId = r.value; app.refresh(); });
    el.querySelectorAll<HTMLInputElement>("input[name=tech]").forEach((r) => r.onchange = () => { if (r.value === "none") delete s.control[ek]; else s.control[ek] = r.value; app.refresh(); });
    const setRate = (v: string, from: "slider" | "number") => {
      const want = +v || 0;
      s.rates[ek] = Math.max(0, Math.min(f.rateMax, want));
      $<HTMLInputElement>("ctlRateN").value = String(s.rates[ek]); $<HTMLInputElement>("ctlRate").value = String(s.rates[ek]);
      if (from === "number" && want !== s.rates[ek]) app.flash(`The ${LABEL[ek]} rate for this source type is limited to 0–${fmt(f.rateMax)} g/s; set to ${fmt(s.rates[ek])} g/s.`);
      app.refresh({ keepControls: true });
    };
    $<HTMLInputElement>("ctlRate").oninput = (e) => setRate((e.target as HTMLInputElement).value, "slider");
    $<HTMLInputElement>("ctlRateN").onchange = (e) => setRate((e.target as HTMLInputElement).value, "number");
    $("ctlRemove").onclick = () => app.removeSource(s);
    $("ctlAlign").onclick = () => { app.alignSection(s); app.refresh(); };
    this.updateControlsNumbers();
  }

  /** Update the numbers in the selected-source panel without rebuilding it (keeps slider focus). */
  updateControlsNumbers() {
    const app = this.app, s = app.selected();
    if (!s || !document.getElementById("ctlKv")) return;
    const ek = app.emitKey(), t = app.techFor(s, ek), rate = s.rates[ek] || 0, after = rate * (1 - (t?.efficiency ?? 0));
    const c = techCost(t, s.family, s.sourceId, rate, app.D.controls);
    const gm = app.D.manifest.fields.find((q) => q.source_id === s.sourceId && q.scenario_id === app.S.scenarioId);
    $("ctlTpy").textContent = `(${fmt(rate * T_PER_YR_PER_G_S)} t/yr if continuous)`;
    const zero = document.getElementById("ctlZero"); if (zero) zero.hidden = rate !== 0;
    $("ctlKv").innerHTML = `<dt>Emitted after control</dt><dd>${fmt(after)} g/s</dd>
      <dt>Removed</dt><dd>${fmt(c.tonsRemoved)} t/yr</dd>
      <dt>Capital (annualised) + fixed O&amp;M</dt><dd>${t ? fmtUsd(c.annualFixedUsd) + "/yr" : "—"}</dd>
      <dt>Variable cost</dt><dd>${t ? fmtUsd(c.annualVariableUsd) + "/yr" : "—"}</dd>
      <dt>Annual cost</dt><dd>${t ? "≈ " + fmtUsd(c.annualUsd) + "/yr" : "—"}</dd>
      <dt>Cost per tonne removed</dt><dd>${c.usdPerTon != null ? "≈ " + fmtUsd(c.usdPerTon) + "/t" : "—"}</dd>
`;
    const gp: Pollutant = app.S.pollutant === "O3" ? "NO2" : app.S.pollutant;   // NOx tracer converts with the NO2 factor
    $("ctlGm").textContent = `This hour, per g/s of ${ek === "NOx" ? "NOx (as NO₂)" : LABEL[ek]}: ground maximum ${gm ? `${fmt(app.conv(gm.ground_max, gp).v, 4)} ${app.conv(gm.ground_max, gp).u} at ${fmt((gm.ground_max_at.r ?? 0) / 1000)} km from the source` : "not available"} (read from the stored field on its 0.25 km rings, so it can differ slightly from the map maximum in the Summary, which uses a 100 m grid).`;
    $("ctlTable").innerHTML = `<caption class="sr-only">Rates and controls for all four pollutants</caption><tr><th>All pollutants</th><th>g/s</th><th>control</th><th>after</th><th>$/yr</th></tr>
      ${EMIT_KEYS.map((p) => { const tt = app.techFor(s, p), cc = techCost(tt, s.family, s.sourceId, s.rates[p] || 0, app.D.controls); return `<tr class="${p === ek ? "cur" : ""}"><td>${LABEL[p]}</td><td>${fmt(s.rates[p] || 0)}</td><td>${tt ? Math.round(tt.efficiency * 100) + " %" : "—"}</td><td>${fmt(app.effRate(s, p))}</td><td>${tt ? fmtUsd(cc.annualUsd) : "—"}</td></tr>`; }).join("")}`;
  }

  // ------------------------------------------------------------------ probe
  renderProbe() {
    const app = this.app, S = app.S, el = $("probeBody");
    if (!S.probe) { el.innerHTML = `<p class="hint">Choose <b>Probe</b> above the map, then click any point (or use the arrow keys on the map).</p>`; return; }
    if (S.pollutant === "O3") { el.innerHTML = `<p class="na">No ozone values in the sandbox.</p>`; return; }
    if (!document.getElementById("probeZ")) {
      el.innerHTML = `<p class="hint" id="probePos"></p>
        <label class="field" for="probeZ">Height above ground <output id="probeZOut"></output></label>
        <input type="range" id="probeZ" min="0" max="1500" step="10" value="0">
        <div id="probeVals" aria-live="polite"></div>`;
      const pz = $<HTMLInputElement>("probeZ");
      pz.oninput = () => { if (S.probe) { S.probe.z = +pz.value; this.renderProbe(); this.app.syncHashLater(); } };
    }
    const p = S.probe, z = p.z;
    $("probePos").textContent = `${relCityHall(p.x, p.y, DOMAIN.cityHall)} · UTM ${Math.round(p.x)} E, ${Math.round(p.y)} N`;
    $("probeZOut").textContent = `${z} m`;
    const pz = $<HTMLInputElement>("probeZ");
    if (+pz.value !== z) pz.value = String(z);
    const key = JSON.stringify([S.scenarioId, app.wd().toFixed(3), p, S.sources.map((s) => [s.tag, s.sourceId, s.x, s.y])]);
    if (!this.probeData || this.probeData.key !== key) {
      if (!S.sources.length) this.probeData = { key, parts: new Map() };
      else {
        const my = ++this.probeSeq, srcs = [...S.sources];
        app.fc.points(S.scenarioId, app.wd(), srcs.map((s) => ({ sourceId: s.sourceId, x: s.x, y: s.y })), Float64Array.of(p.x), Float64Array.of(p.y), Float64Array.of(z)).then((vals) => {
          if (my !== this.probeSeq) return;
          this.probeData = { key, parts: new Map(srcs.map((s, i) => [s.tag, vals[i][0]])) };
          this.renderProbe();
        }).catch((e) => console.warn(e));
      }
    }
    const pending = this.probeData?.key !== key;
    const ek = app.emitKey();
    const parts = S.sources.map((s) => ({ s, v: (this.probeData?.parts.get(s.tag) ?? 0) * app.effRate(s, ek) })).filter((q) => q.v > 0).sort((a, b) => b.v - a.v);
    let roads = 0, roadsNA = false;
    if (app.roadsActive()) for (const t of app.tiersOn()) {
      const k = RoadMaps.key(S.scenarioId, t, app.roadPol()!);
      if (z === 0) { const m = app.roadMaps.groundReady.get(k); if (m) roads += cellValue(m, app.grid, p.x, p.y) * S.roads.trafficScale; }
      else {
        const vm = app.roadMaps.vertReady.get(k);
        if (!vm) { roadsNA = !app.roadMaps.verticalAvailable; if (app.roadMaps.verticalAvailable && !this.vertAsked.has(k)) { this.vertAsked.add(k); app.roadMaps.loadVertical(S.scenarioId, t, app.roadPol()!).then(() => this.renderProbe()); } continue; }
        const v = verticalValue(vm, p.x, p.y, z);
        if (v == null) roadsNA = true; else roads += v * S.roads.trafficScale;
      }
    }
    const bg = z === 0 ? app.bgUg() : 0;
    const total = bg + roads + parts.reduce((a, q) => a + q.v, 0), tot = Math.max(total, 1e-12);
    const flags = app.limitFlagsAt(p.x, p.y);
    const bar = (lab: string, v: number, col = "#555") => `<span>${lab}</span><div class="bar" aria-hidden="true"><span style="width:${(100 * v / tot).toFixed(1)}%;background:${col}"></span></div><span class="v">${esc(app.showC(v))}</span>`;
    const incC = app.conv(total - bg);
    $("probeVals").innerHTML = `<div class="big">${esc(app.showC(total))} <small>${z === 0 ? "total at ground" : "plume increment at " + z + " m"}${pending ? " · updating" : ""}</small></div>
      ${z === 0 ? `<p class="hint">Increment (sources + roads, total minus background): <b>${esc(fmt(incC.v, 4))} ${incC.u}</b></p>` : ""}
      <div class="contrib">
        ${z === 0 ? bar("bg", bg, "#aaa") : ""}
        ${roads > 0 ? bar("roads", roads, "#888") : ""}
        ${parts.slice(0, 8).map((q) => bar("S" + q.s.tag, q.v)).join("")}
      </div>
      ${z > 0 ? `<p class="hint">Above ground the background is not included (it is measured at ground level).${roadsNA ? " Road values above 500 m are not computed and are left out." : app.roadsActive() ? " Road values aloft come from a coarse 200 m grid." : ""}</p>` : ""}
      ${flags.map(([k, t]) => `<div class="flagline"><button class="i-mark" data-lim="${k}" aria-label="About: ${esc(LIMITS[k].title)}">i</button><span>${esc(t[0].toUpperCase() + t.slice(1))}: ${esc(LIMITS[k].title.toLowerCase())}; read this value with care.</span></div>`).join("")}`;
    this.bindLimits($("probeVals"));
  }

  // ------------------------------------------------------------------ summary
  renderSummary() {
    const app = this.app, S = app.S, el = $("summaryBody");
    if (S.pollutant === "O3" || !app.field) { el.innerHTML = `<p class="na">No ozone summary in the sandbox. The Linearity edge module covers ozone.</p>`; return; }
    const F = app.field, k = F.maxIdx, g = app.grid, i = k % g.nx, j = Math.floor(k / g.nx);
    const mx = g.x0 + (i + 0.5) * g.d, my = g.y0 + (j + 0.5) * g.d;
    const st = app.standard();
    const pa = app.partsAtCell(k);
    const parts = pa.parts.filter((q) => q.v > 1e-4 * pa.total).sort((a, b) => b.v - a.v);
    const roadV = pa.roads.reduce((a, r) => a + r.v, 0);
    const flags = F.incMax > 0 ? app.limitFlagsAt(mx, my) : [];
    let cost = NO_COST;
    for (const s of S.sources) for (const p of EMIT_KEYS) cost = addCosts(cost, techCost(app.techFor(s, p), s.family, s.sourceId, s.rates[p] || 0, app.D.controls));
    const bar = (lab: string, v: number, col = "#555") => `<span>${lab}</span><div class="bar" aria-hidden="true"><span style="width:${(100 * v / Math.max(pa.total, 1e-12)).toFixed(1)}%;background:${col}"></span></div><span class="v">${esc(app.showC(v))}</span>`;
    const stdHTML = !st ? `<p class="na">No reference level chosen.</p>` : `
      <p><b>${esc(st.name)}</b>: ${esc(app.levelText(st))}</p>
      <p class="hint">${st.why.includes(st.form) ? esc(st.why) : `Form: ${esc(st.form)}. ${esc(st.why)}`}</p>`;
    const perf = app.perf;
    el.innerHTML = `
      <div class="hint">Highest ground-level ${LABEL[S.pollutant]} on the map, this hour</div>
      <div class="big">${esc(app.showC(F.max))} <small>total</small></div>
      ${F.incMax > 0 ? `<p class="hint">${relCityHall(mx, my, DOMAIN.cityHall)}${parts.length ? `; ${fmt(Math.hypot(mx - parts[0].s.x, my - parts[0].s.y) / 1000)} km from S${parts[0].s.tag}${parts.length > 1 ? " (its largest source contributor)" : ""}` : ""}. Background ${esc(app.showC(F.background))}; plumes and roads add ${esc(app.showC(F.max - F.background))} there.</p>
      <div class="contrib">${roadV > 0 ? bar("roads", roadV, "#888") : ""}${parts.slice(0, 5).map((q) => bar("S" + q.s.tag, q.v)).join("")}</div>`
        : `<p class="hint">The map shows the background only (${esc(app.showC(F.background))}).</p>`}
      ${flags.map(([q, t]) => `<div class="flagline"><button class="i-mark" data-lim="${q}" aria-label="About: ${esc(LIMITS[q].title)}">i</button><span>The maximum is in a low-accuracy region: ${esc(t)}.</span></div>`).join("")}
      <div class="sum-block"><div class="hint">Reference level: <button class="linkbtn" id="sumStd">${st ? "change" : "choose one"}</button></div>${stdHTML}
        <div class="flagline grey"><button class="i-mark" data-lim="one_hour_std" aria-label="About: one hour is too short for exceedances">i</button><span>One modelled hour is too short for an exceedance to be meaningful: standards are statistics over months to years, so the level is shown for reference only.</span></div></div>
      <div class="sum-block"><div class="hint">Controls (all placed sources, all four pollutants) <span class="approx">approximate costs${app.D.controls.costYear ? ", " + app.D.controls.costYear + " $" : ""}</span></div>
        <dl class="kv"><dt>Emissions removed</dt><dd>${fmt(cost.tonsRemoved)} t/yr</dd>
        <dt>Annual cost</dt><dd>${cost.annualUsd ? "≈ " + fmtUsd(cost.annualUsd) + "/yr" : "—"}</dd>
        <dt>of which capital + fixed O&amp;M</dt><dd>${cost.annualUsd ? fmtUsd(cost.annualFixedUsd) + "/yr" : "—"}</dd>
        <dt>Average</dt><dd>${cost.usdPerTon != null ? "≈ " + fmtUsd(cost.usdPerTon) + " per t removed" : "—"}</dd></dl>
        ${app.D.controls.fallback ? `<p class="hint">Fallback costs (variable only), pending controls.json.</p>` : ""}</div>
      <div class="flagline grey"><button class="i-mark" data-lim="steady" aria-label="About: one steady hour">i</button><span>One steady hour: every value is a 1-hour average for this weather hour only.</span></div>
      ${S.instructor ? `<p class="perf">Engine: ${S.sources.length} cached source maps${app.roadsActive() ? " plus roads" : ""} combined in ${perf.combineMs.toFixed(1)} ms, painted in ${perf.paintMs.toFixed(1)} ms${perf.lastHourChangeMs != null ? `; last hour change ${Math.round(perf.lastHourChangeMs)} ms` : ""}${perf.lastPlaceMs != null ? `; last place or move ${Math.round(perf.lastPlaceMs)} ms` : ""}.</p>` : ""}`;
    $("sumStd").onclick = () => this.openModal("standardModal");
    this.bindLimits(el);
  }

  // ------------------------------------------------------------------ legends
  renderLegend() {
    const app = this.app, S = app.S, el = $("mapLegend");
    if (S.pollutant === "O3" || !S.layers.conc) { el.classList.add("hidden"); return; }
    el.classList.remove("hidden");
    const br = rampBreaks(app.scaleLoUg()), lo = br[0], hi = lo * Math.pow(10, SCALE_DECADES);
    const pos = (v: number) => Math.max(0, Math.min(100, (Math.log10(v / lo) / SCALE_DECADES) * 100));
    const st = app.standard(), bg = app.bgUg();
    const ticks = [0, 1, 2, 3].map((d) => ({ v: lo * Math.pow(10, d), p: (d / SCALE_DECADES) * 100 }));
    el.innerHTML = `<div class="scale">
        <div><b>${LABEL[S.pollutant]}</b>${S.pollutant === "NO2" ? " (tracer upper limit: all emitted NOx counted as NO₂)" : ""}, ground level, ${S.show === "total" ? "background + plumes + roads" : "plume and road increment only"} (fixed scale for ${LABEL[S.pollutant]})</div>
        <div class="ramp" role="img" aria-label="Colour scale from ${esc(app.showC(lo))} (light) to ${esc(app.showC(hi))} or more (dark), logarithmic">${RAMP.map((c) => `<span style="background:${c}"></span>`).join("")}
          ${st && st.pol === S.pollutant && st.ug >= lo ? `<i class="ref-mark" style="left:${pos(st.ug)}%" data-label="${esc(st.avg)} level ${esc(app.levelShown(st))}"></i>` : ""}
          ${S.show === "total" && bg >= lo ? `<i class="bg-mark" style="left:${pos(bg)}%" title="Background"></i>` : ""}</div>
        <div class="ticks">${ticks.map((t) => `<span style="left:${t.p}%">${esc(app.showC(t.v))}</span>`).join("")}</div>
      </div>
      <div class="seg small" role="radiogroup" aria-label="Map shows"><button role="radio" data-show="total" aria-checked="${S.show === "total"}" class="${S.show === "total" ? "active" : ""}">Total</button><button role="radio" data-show="increment" aria-checked="${S.show === "increment"}" class="${S.show === "increment" ? "active" : ""}">Increment</button></div>
      <span class="hint">${S.show === "total" ? `Grey tick: background ${esc(app.showC(bg))}.` : ""} ${st && st.pol === S.pollutant ? "Dashed mark: reference level (not an exceedance test)." : ""} ${S.show === "total" ? `Uncoloured: plumes and roads add less than ${esc(app.showC(lo))} (background alone).` : `Uncoloured: increment below ${esc(app.showC(lo))}.`}</span>
      ${!S.layers.limits ? `<button class="linkbtn" id="legendLimits">Show the model limits on the map</button>` : ""}`;
    el.querySelectorAll<HTMLButtonElement>("[data-show]").forEach((b) => b.onclick = () => { S.show = b.dataset.show as "total" | "increment"; app.refresh({ keepControls: true }); });
    const ll = document.getElementById("legendLimits");
    if (ll) ll.onclick = () => { S.layers.limits = true; app.refresh({ keepControls: true }); };
  }

  renderLimitsLegend() {
    const el = $("limitsLegend"), on = this.app.S.layers.limits;
    el.classList.toggle("hidden", !on);
    el.innerHTML = `<b>Model limits shown:</b>
      <button data-lim="near_stack"><span class="sw hatch"></span> within ~250 m of a stack</button>
      <button data-lim="near_road"><span class="sw road"></span> within ~50 m of a road</button>
      <button data-lim="area_inside"><span class="sw area"></span> inside an area source</button>
      <button data-lim="steady"><span class="i-mark" aria-hidden="true">i</span> one steady hour</button>`;
    this.bindLimits(el);
  }

  // ------------------------------------------------------------------ modals and pop-ups
  private lastFocus: HTMLElement | null = null;
  openModal(id: string) {
    if (id === "scenarioModal") this.renderScenarioModal();
    if (id === "standardModal") this.renderStandardModal();
    this.lastFocus = document.activeElement as HTMLElement;
    $(id).classList.remove("hidden");
    ($(id).querySelector(".on, input:checked, button") as HTMLElement | null)?.focus();
  }
  closeModals() {
    let was = false;
    document.querySelectorAll(".modal").forEach((m) => { if (!m.classList.contains("hidden")) was = true; m.classList.add("hidden"); });
    if (was) this.lastFocus?.focus();
  }

  private renderScenarioModal() {
    const app = this.app, S = app.S;
    $("scenarioCards").innerHTML = app.D.scenarios.map((s) => {
      const b = app.D.backgrounds[s.id] || {};
      const ziPx = Math.min(1, s.zi_effective_m / 2500) * 56;
      const ang = (s.wd_deg + 180) * Math.PI / 180, ax = Math.sin(ang) * 16, ay = -Math.cos(ang) * 16;
      const bgTxt = (p: Pollutant) => { const v = b[p]; return v?.ug != null ? `${LABEL[p]} ${app.showC(v.ug, p)}` : `${LABEL[p]} —`; };
      return `<div class="scn-card ${s.id === S.scenarioId ? "on" : ""}">
        <h3>${esc(s.label)}</h3><div class="hint">${esc(s.date)}, hour ending ${pad2(s.hour)}:00 LST</div>
        <svg class="sketch" viewBox="0 0 200 70" preserveAspectRatio="none" aria-hidden="true">
          <rect x="0" y="${64 - ziPx}" width="120" height="${ziPx}" fill="#e6e6e1"/><line x1="0" x2="120" y1="${64 - ziPx}" y2="${64 - ziPx}" stroke="#a3001c" stroke-dasharray="4 3"/>
          <text x="4" y="${Math.max(10, 60 - ziPx)}" font-size="9" fill="#a3001c">zi ${Math.round(s.zi_effective_m)} m</text>
          <line x1="0" x2="200" y1="64" y2="64" stroke="#777"/>
          <circle cx="160" cy="34" r="22" fill="#fff" stroke="#bbb"/><line x1="${160 - ax}" y1="${34 - ay}" x2="${160 + ax}" y2="${34 + ay}" stroke="#111" stroke-width="2.5"/>
          <circle cx="${160 + ax}" cy="${34 + ay}" r="3" fill="#111"/></svg>
        <p>${esc(NEUTRAL_DESC[s.id] || "")}</p>
        <dl class="kv"><dt>Wind</dt><dd>from ${Math.round(s.wd_deg)}°, ${s.ws_m_s.toFixed(1)} m/s</dd>
          <dt>Stability</dt><dd>${s.L_m > 1000 ? "near-neutral" : s.L_m > 0 ? "stable" : "convective"}</dd>
          <dt>L</dt><dd>${fmt(s.L_m)} m</dd><dt>zi (step at)</dt><dd>${Math.round(s.zi_effective_m)} m</dd>
          <dt>Cloud, temp.</dt><dd>${s.cloudTenths ?? "—"}/10, ${((s.temp_K ?? 273.15) - 273.15).toFixed(0)} °C</dd><dt>Road traffic</dt><dd>${Math.round(s.trafficFactor * 100)} % of daily mean</dd></dl>
        <table class="bg"><tr><td>Background:</td><td>${bgTxt("SO2")}</td><td>${bgTxt("NO2")}</td></tr>
          <tr><td></td><td>${bgTxt("CO")} ${b.CO?.flags.includes("urban_monitor") ? '<span class="flag-dot amber" title="Urban monitors: likely overstates a regional background">!</span>' : ""}</td><td>${bgTxt("PM25")}</td></tr>
          <tr><td></td><td>${bgTxt("O3")}</td><td></td></tr></table>
        <div class="hint">Model notes: ${(SCN_LIMITS[s.id] || []).map((k) => `<button class="i-mark" data-lim="${k}" aria-label="About: ${esc(LIMITS[k].title)}">i</button> ${esc(LIMITS[k].title.toLowerCase())}`).join("; ")}</div>
        <button class="btn ${s.id === S.scenarioId ? "" : "primary"}" data-scn="${s.id}">${s.id === S.scenarioId ? "Current hour" : "Use this hour"}</button>
      </div>`;
    }).join("");
    $("scenarioCards").querySelectorAll<HTMLButtonElement>("[data-scn]").forEach((b) => b.onclick = () => { this.closeModals(); app.setScenario(b.dataset.scn!); });
    this.bindLimits($("scenarioCards"));
  }

  private renderStandardModal() {
    const app = this.app, S = app.S;
    const row = (s: typeof app.D.standards[number]) => `<div class="std-row ${S.standardId === s.id ? "on" : ""}" data-std="${s.id}">
      <input type="radio" name="std" id="std_${s.id}" ${S.standardId === s.id ? "checked" : ""}><label for="std_${s.id}"><b>${LABEL[s.pol]}</b></label><span>${esc(s.name)} · <span class="lvl">${esc(app.levelText(s))}</span></span>
      <span class="pill ${s.sameAveraging ? "ok" : "no"}">${s.sameAveraging ? "same averaging time" : esc(s.avg) + " average"}</span>
      <span class="why">${esc(s.why)}${s.pol !== S.pollutant ? " Choosing it switches the map to " + LABEL[s.pol] + "." : ""}</span></div>`;
    const map = app.D.standards.filter((s) => s.pol !== "O3");
    $("standardList").innerHTML = `
      <div class="std-group"><h3>1-hour standards (same averaging time as the map)</h3>${map.filter((s) => s.sameAveraging).map(row).join("")}</div>
      <div class="std-group"><h3>Longer averaging times</h3>${map.filter((s) => !s.sameAveraging).map(row).join("")}</div>
      <div class="std-group"><h3>Other</h3><div class="std-row ${S.standardId === "none" ? "on" : ""}" data-std="none"><input type="radio" name="std" id="std_none" ${S.standardId === "none" ? "checked" : ""}><label for="std_none"></label><span>No reference level</span><span></span></div></div>`;
    $("standardList").querySelectorAll<HTMLElement>(".std-row").forEach((r) => {
      const pick = () => {
        S.standardId = r.dataset.std!;
        const s = app.standard();
        if (s && s.pol !== S.pollutant) S.pollutant = s.pol;
        this.renderStandardModal(); app.refresh();
        (document.getElementById("std_" + S.standardId) as HTMLInputElement | null)?.focus();
      };
      r.onclick = pick;
      (r.querySelector("input") as HTMLInputElement).onchange = pick;
    });
  }

  bindLimits(root: HTMLElement) {
    root.querySelectorAll<HTMLElement>("[data-lim]").forEach((b) => b.onclick = (e) => { e.stopPropagation(); this.showLimit(b.dataset.lim!, b); });
  }
  showLimit(key: string, anchor: HTMLElement) {
    const L = LIMITS[key], pop = $("limitPop"), r = anchor.getBoundingClientRect();
    pop.innerHTML = `<h3>Model limit: ${esc(L.title)}</h3><p>${esc(L.text)}</p><p class="where">Shown: ${esc(L.where)}</p><button class="btn" id="popClose">Close</button> <button class="linkbtn" id="popAll">All model limits</button>`;
    pop.classList.remove("hidden");
    const w = Math.min(360, window.innerWidth - 20);
    pop.style.left = Math.max(10, Math.min(window.innerWidth - w - 10, r.left - 20)) + "px";
    pop.style.top = Math.max(10, Math.min(window.innerHeight - pop.offsetHeight - 10, r.bottom + 6)) + "px";
    $("popClose").onclick = () => { pop.classList.add("hidden"); anchor.focus(); };
    $("popAll").onclick = () => { pop.classList.add("hidden"); this.closeModals(); this.app.setScreen("about"); document.getElementById("about-limits")?.scrollIntoView(); };
    $("popClose").focus();
  }
}

export type { PlacedSource, EmitKey };
export { CONTROL_KEY };
