// About, model limits, data and provenance, and the instructor panel (instructor view only:
// teaching and artifact notes, settings). Instructor view is a plain toggle or ?instructor=1;
// it is not a secret.
import { LABEL, LIMITS } from "../data/catalogue";
import type { App } from "./app";
import { esc, fmt, pad2 } from "./format";
import { PUBLIC_SITE } from "../config";

export function renderAbout(app: App) {
  const el = document.getElementById("aboutBody")!;
  const D = app.D, M = D.manifest, S = app.S;
  const prov = (M.fields[0]?.provenance || {}) as Record<string, string>;
  const lim = Object.values(LIMITS).map((L) => `<tr><td><b>${esc(L.title)}</b></td><td>${esc(L.text)}</td><td class="hint">${esc(L.where)}</td></tr>`).join("");
  const pol = (["SO2", "CO", "NO2", "PM25", "O3"] as const).map((p) => {
    const i = D.pollutantInfo[p];
    const lv = D.standards.filter((s) => s.pol === p).map((s) => `${esc(s.avg)}: ${esc(app.levelText(s))}`).join("; ");
    return i ? `<tr><td><b>${LABEL[p]}</b></td><td>${lv || esc(i.naaqsText || "")}</td><td>${(i.caveats || []).map(esc).join(" ")}</td></tr>` : "";
  }).join("");
  const conv = (["SO2", "NO2", "CO", "O3"] as const).map((g) => `${LABEL[g]} ${(D.ugPerPpb[g] ?? 0).toPrecision(g === "CO" || g === "O3" ? 5 : 4)}`).join(", ") + " µg/m³ per ppb (from backgrounds.json)";
  const refs = Object.entries(D.controls.references).map(([k, v]) => `<li><code>${esc(k)}</code> ${esc(v)}</li>`).join("");
  const scn = D.scenarios.map((s) => `<tr><td><b>${esc(s.label)}</b><br><span class="hint">${esc(s.date)}, hour ending ${pad2(s.hour)}:00 LST</span></td><td>${esc(s.teaching || "")}</td><td><ul>${(s.artifacts || []).map((a) => `<li>${esc(a)}</li>`).join("")}</ul></td></tr>`).join("");
  const st = D.status;
  const perf = app.perf.samples.slice(-12).map((p) => `<li>${esc(p.what)}: ${Math.round(p.ms)} ms</li>`).join("");
  el.innerHTML = `
    <section class="panel full">
      <h2>About this sandbox</h2>
      <p>Place emission sources on a 30 × 30 km map of Philadelphia and see ground-level and vertical concentration fields for one hour of real 2024 weather. Every source type was run once in AERMOD at an emission of 1 g/s for each weather hour. The sandbox multiplies each stored field by your emission rate and by (1 − control efficiency), moves it to the source's cell, and adds the fields, the existing road network (precomputed) and the regional background together. The background is added once.</p>
      <p>Adding fields this way is exact for a pollutant that does not react, on flat terrain, within the same hour (tests against direct AERMOD runs agreed to output rounding). Away from the regions listed below, the sandbox's ground-level values are within about 5 % of a direct AERMOD run (95th percentile) for stacks, area and volume sources.</p>
      <p class="hint">Keyboard: Tab reaches every control. On the focused map, the arrow keys move the selected source (Shift for 2 km steps) or the placement cursor, Enter places, Delete removes the selected source, and Esc leaves placement or closes a window.</p>
      <label class="switch"><input type="checkbox" id="instrToggle" ${S.instructor ? "checked" : ""}> Instructor view (shows ${PUBLIC_SITE ? "the instructor settings" : "teaching notes and settings"}; also <code>?instructor=1</code> in the address)</label>
    </section>
    <section class="panel full" id="about-limits">
      <h2>Model limits shown in the sandbox</h2>
      <p class="hint">These are limitations of AERMOD or of the stored fields. They are labelled where they occur rather than hidden: (i) buttons beside values, amber flags when a value lies in a low-accuracy region, and the "Model limits" map layer.</p>
      <table><tr><th>Limit</th><th>What it means</th><th>Where it appears</th></tr>${lim}</table>
    </section>
    <section class="panel">
      <h2>Pollutants and reference levels</h2>
      <p id="about-units">Units: the gases (SO₂, NO₂, CO and O₃) are shown in ppb by default, with µg/m³ as an option; PM₂.₅ is always in µg/m³. The engine works in µg/m³, and the display converts at 25 °C and 1 atm with ${conv}. The NO₂ map counts all emitted NOx as NO₂ (the tracer upper limit), so it converts with the NO₂ factor.</p>
      <table><tr><th></th><th>NAAQS levels (shown in the current units)</th><th>Notes</th></tr>${pol}</table>
      <ul>${D.generalCaveats.map((c) => `<li>${esc(c)}</li>`).join("")}</ul>
    </section>
    <section class="panel">
      <h2>Data and provenance</h2>
      <ul>
        <li>Fields: ${M.totals?.n_fields ?? M.fields.length} unit-emission fields (${M.totals ? (M.totals.bytes / 1e6).toFixed(0) + " MB, " + (M.totals.gzip_bytes / 1e6).toFixed(0) + " MB gzipped" : ""}), format ${esc(M.format)} v${M.format_version}, grid ${esc(prov.grid_version || "")}, ${M.grids.polar.z_m.length} heights to ${M.grids.polar.z_m[M.grids.polar.z_m.length - 1]} m.</li>
        <li>Model: AERMOD ${esc(prov.aermod_version || "")} through pyAERMOD (commit ${esc((prov.pyaermod_commit || "").slice(0, 7))}), flat terrain, urban option (Philadelphia, population 1.6 million).</li>
        <li>Weather: PHL surface station (KPHL) and Sterling VA upper air, 2024, processed with AERMET 24142.</li>
        <li>Backgrounds: EPA AirData hourly files for 2024, regional monitors upwind where possible.</li>
        <li>Roads: ${D.roads.roads.length} tier 1 and 2 roads; ${esc(D.roads.attribution)}. ${esc(D.roads.trafficDataNote)} Emission factors are approximate fleet averages, not a MOVES run.${D.roadBaselines ? " Road concentration maps were precomputed offline with the project's Python engine at each hour's observed wind and traffic." : ""}</li>
        <li>Control costs: ${D.controls.approximate ? "approximate teaching values" : ""}${D.controls.costYear ? ` in ${D.controls.costYear} dollars` : ""}; annual cost = capital × (capital recovery factor + fixed O&amp;M fraction) + variable $/t × tonnes removed${D.controls.interestRate != null ? `, interest rate ${(D.controls.interestRate * 100).toFixed(1)} %` : ""}. Tonnes assume continuous operation at the hour's rate (g/s × 31.536 = t/yr).</li>
      </ul>
      ${st.missing.length ? `<p class="flagline"><span>Fallback data in use for: ${st.missing.map(esc).join("; ")}.</span></p>` : ""}
      <details><summary>Cost references</summary><ul>${refs}</ul></details>
    </section>
    <section class="panel full instr ${S.instructor ? "" : "hidden"}" id="instrPanel">
      <h2>Instructor settings</h2>
      <p class="hint">Settings travel with a saved file or a shared link, so a hand-out opens the same way for students.</p>
      <label class="switch"><input type="checkbox" id="setRotation" ${S.settings.allowRotation ? "checked" : ""}> Allow students to rotate the wind direction (the road baseline is hidden while rotated)</label><br>
      <label class="switch"><input type="checkbox" id="setLimits" ${S.settings.limitsOnStart ? "checked" : ""}> Turn the model-limits layer on when this configuration opens</label>
      <label class="field" for="setTitle">Configuration title (shown in the top bar)</label>
      <input type="text" id="setTitle" value="${esc(S.title)}" maxlength="80" style="max-width:420px">
      <p><button class="btn" id="instrShare">Copy a link to the current configuration</button> <button class="btn" id="instrSave">Save it as a file</button></p>
      <h3>Teaching notes and expected model behaviour per weather hour</h3>
      ${PUBLIC_SITE ? `<p class="hint">Not included in this public build. The teaching notes and the expected model behaviour for each hour are in the instructor guide (<code>docs/instructor.md</code>).</p>`
        : `<p class="hint">From <code>config/scenarios.yaml</code>. They describe outcomes, so students see neutral descriptions instead.</p>
      <table><tr><th>Hour</th><th>Teaching note</th><th>Expected model behaviour (artifacts)</th></tr>${scn}</table>`}
      <h3>Linearity module records in this configuration</h3>
      ${S.linearity.length ? `<p>${S.linearity.length} entries, oldest first.</p><ol class="lin-records">${S.linearity.map(linRecord).join("")}</ol>` : "<p>None.</p>"}
      <h3>Performance (this session)</h3>
      <p class="hint">Last combine ${fmt(app.perf.combineMs)} ms, paint ${fmt(app.perf.paintMs)} ms; ${app.fc.n} field workers.</p>
      <ul>${perf || "<li>No timed actions yet.</li>"}</ul>
    </section>`;
  const it = document.getElementById("instrToggle") as HTMLInputElement;
  it.onchange = () => { app.setInstructor(it.checked); renderAbout(app); };
  if (!S.instructor) return;
  (document.getElementById("setRotation") as HTMLInputElement).onchange = (e) => { S.settings.allowRotation = (e.target as HTMLInputElement).checked; if (!S.settings.allowRotation) S.windFromDeg = null; app.syncHashLater(); };
  (document.getElementById("setLimits") as HTMLInputElement).onchange = (e) => { S.settings.limitsOnStart = (e.target as HTMLInputElement).checked; if (S.settings.limitsOnStart) S.layers.limits = true; app.syncHashLater(); };
  (document.getElementById("setTitle") as HTMLInputElement).oninput = (e) => {
    S.title = (e.target as HTMLInputElement).value;
    const t = document.getElementById("configTitle")!; t.textContent = S.title; t.classList.toggle("hidden", !S.title);
    app.syncHashLater();
  };
  document.getElementById("instrShare")!.onclick = async () => { const url = await app.shareLink(); await copyText(url); app.toast("Link copied to the clipboard."); };
  document.getElementById("instrSave")!.onclick = () => app.saveFile();
}

export async function copyText(s: string): Promise<boolean> {
  try { await navigator.clipboard.writeText(s); return true; } catch {
    const ta = document.createElement("textarea"); ta.value = s; document.body.appendChild(ta); ta.select();
    const ok = document.execCommand("copy"); ta.remove(); return ok;
  }
}

/** One linearity record as a readable line for the instructor (predictions, notes, marked points). */
function linRecord(r: { step: string; prediction?: unknown; observed?: unknown; t: number }): string {
  const p = (r.prediction ?? {}) as Record<string, any>, o = (r.observed ?? {}) as Record<string, any>;
  const when = new Date(r.t).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
  const where = (q: Record<string, any>) => [q.scenario, q.setting].filter(Boolean).join(", ");
  let txt: string;
  if (r.step === "predict") txt = `Prediction (${where(p)}): NOx ${p.tracer_nox_ppb} ppb, O₃ change ${p.o3_change_ppb} ppb; expected ${p.expectation || "—"}; reason: ${p.reason || "—"}`;
  else if (r.step === "compare") txt = `Compared (${where(o)}): O₃ A ${o.o3?.a}, B ${o.o3?.b}, sum ${o.o3?.sum}, both ${o.o3?.both} ppb`;
  else if (r.step === "note") txt = `Note (${where(o)}): ${o.text}`;
  else if (r.step === "explore-pin") txt = `Marked point (${o.scenario}): NOx ${o.nox_ppb} ppb, VOC ${o.voc_ppbC} ppbC; A ${o.o3?.a}, B ${o.o3?.b}, sum ${o.o3?.sum}, both ${o.o3?.both} ppb`;
  else if (r.step === "explore-unpin") txt = `Removed marked point ${Number(o.index) + 1}`;
  else if (r.step === "no2-predict") txt = `NO₂ prediction: ${p.choice}${p.factor ? `, factor ${p.factor}` : ""}`;
  else txt = r.step;
  return `<li><span class="hint">${esc(when)}</span> ${esc(txt)}</li>`;
}
