// Application state and its serialisation (Checkpoint 3a, decision 15): a configuration can be
// saved and shared as a link (URL hash) or as a JSON file, and loaded back, including the
// linearity module's `record` entries.
import type { EmitKey, LinearityRecord, Pollutant } from "../types";
import type { DisplayUnits } from "../data/units";

export interface PlacedSource {
  tag: number;                                   // S1..S12, stable across edits
  family: string;                                // power_plant_stack | industrial_stack | area | volume
  sourceId: string;                              // PP100 ... VOL30 (changes with stack height)
  cell: { i: number; j: number };                // 500 m placement cell
  x: number; y: number;                          // cell centre, UTM 18N (m)
  rates: Record<EmitKey, number>;                // g/s, all four pollutants (decision 8)
  control: Partial<Record<EmitKey, string>>;     // technology id per pollutant ("none" or absent = no control)
}

export interface Settings {
  allowRotation: boolean;       // instructor setting (decision 1)
  limitsOnStart: boolean;       // instructor setting: model-limits layer on when a configuration opens
}

export interface AppState {
  screen: "sandbox" | "linearity" | "about";
  scenarioId: string;
  windFromDeg: number | null;   // null = observed
  pollutant: Pollutant;
  units: DisplayUnits;          // gases in ppb (default) or µg/m³; PM2.5 is always µg/m³
  show: "total" | "increment";
  standardId: string;           // a StandardRef id or "none"
  sources: PlacedSource[];
  nextTag: number;
  selected: number | null;
  roads: { tier1: boolean; tier2: boolean; trafficScale: number };   // trafficScale 0..2 (0-200 %)
  layers: { conc: boolean; roads: boolean; grid: boolean; section: boolean; limits: boolean };
  section: { a: { x: number; y: number }; b: { x: number; y: number }; zTop: number } | null;
  expanded: boolean;
  probe: { x: number; y: number; z: number } | null;
  mode: "select" | "probe" | "place";
  placeFamily: string | null;
  settings: Settings;
  instructor: boolean;          // URL flag ?instructor=1 or the toggle on the About tab; not saved
  linearity: LinearityRecord[];
  title: string;                // optional configuration title (instructor hand-outs)
}

export function initialState(scenarioId: string): AppState {
  return {
    screen: "sandbox", scenarioId, windFromDeg: null, pollutant: "SO2", units: "ppb", show: "total", standardId: "SO2_1hour",
    sources: [], nextTag: 1, selected: null,
    roads: { tier1: true, tier2: true, trafficScale: 1 },
    layers: { conc: true, roads: true, grid: false, section: true, limits: false },
    section: null, expanded: false, probe: null, mode: "select", placeFamily: null,
    settings: { allowRotation: false, limitsOnStart: false }, instructor: false, linearity: [], title: "",
  };
}

// ------------------------------------------------------------------ saved configuration
export const CONFIG_FORMAT = "aq-sandbox-config";
/** Version 2 (2026-10-28): `units` is "ppb" (default) or "ug". Version 1 files carried "ug" as the
 *  old default or "native" (ppb/ppm); both open in ppb. */
export const CONFIG_VERSION = 2;

export interface SavedConfig {
  format: typeof CONFIG_FORMAT;
  version: number;
  saved: string;
  title?: string;
  scenario: string;
  wind_from_deg: number | null;
  pollutant: Pollutant;
  units?: DisplayUnits | "native";
  show: "total" | "increment";
  standard: string;
  sources: { family: string; source_id: string; x: number; y: number; rates_g_s: Record<EmitKey, number>; control: Partial<Record<EmitKey, string>> }[];
  roads: { tier1: boolean; tier2: boolean; traffic_scale: number };
  layers?: Partial<AppState["layers"]>;
  section: AppState["section"];
  probe: AppState["probe"];
  settings: Settings;
  linearity: LinearityRecord[];
}

export function toConfig(s: AppState): SavedConfig {
  return {
    format: CONFIG_FORMAT, version: CONFIG_VERSION, saved: new Date().toISOString(), title: s.title || undefined,
    scenario: s.scenarioId, wind_from_deg: s.windFromDeg, pollutant: s.pollutant, units: s.units, show: s.show, standard: s.standardId,
    sources: s.sources.map((q) => ({ family: q.family, source_id: q.sourceId, x: q.x, y: q.y, rates_g_s: { ...q.rates }, control: { ...q.control } })),
    roads: { tier1: s.roads.tier1, tier2: s.roads.tier2, traffic_scale: s.roads.trafficScale },
    layers: { ...s.layers }, section: s.section, probe: s.probe, settings: { ...s.settings }, linearity: [...s.linearity],
  };
}

export interface ApplyContext {
  scenarioIds: string[];
  familyOfSource: Record<string, string>;
  cellOf(x: number, y: number): { i: number; j: number } | null;
  cellCentre(c: { i: number; j: number }): { x: number; y: number };
  maxSources: number;
}

/** Apply a saved configuration; returns warnings for anything skipped. */
export function applyConfig(s: AppState, c: SavedConfig, ctx: ApplyContext): string[] {
  const warn: string[] = [];
  if (c.format !== CONFIG_FORMAT) throw new Error("This file is not an Air Quality Sandbox configuration.");
  if (ctx.scenarioIds.includes(c.scenario)) s.scenarioId = c.scenario; else warn.push(`Unknown weather hour ${c.scenario}; kept ${s.scenarioId}.`);
  s.windFromDeg = typeof c.wind_from_deg === "number" ? ((c.wind_from_deg % 360) + 360) % 360 : null;
  if (["SO2", "CO", "NO2", "PM25", "O3"].includes(c.pollutant)) s.pollutant = c.pollutant;
  // Units: ppb unless a version 2 (or later) file chose µg/m³. Version 1 files held "ug" only as the
  // old default, so they open in ppb like everything else.
  s.units = (c.version ?? 1) >= 2 && c.units === "ug" ? "ug" : "ppb";
  s.show = c.show === "increment" ? "increment" : "total";
  s.standardId = c.standard || "none";
  s.sources = []; s.nextTag = 1; s.selected = null;
  const used = new Set<string>();
  for (const q of c.sources || []) {
    if (s.sources.length >= ctx.maxSources) { warn.push(`Only ${ctx.maxSources} sources can be placed; the rest were skipped.`); break; }
    const fam = ctx.familyOfSource[q.source_id];
    if (!fam) { warn.push(`Unknown source type ${q.source_id}; skipped.`); continue; }
    const cell = ctx.cellOf(q.x, q.y);
    if (!cell) { warn.push(`A source outside the map was skipped.`); continue; }
    const key = `${cell.i},${cell.j}`;
    if (used.has(key)) { warn.push(`Two sources in one 500 m cell; the second was skipped.`); continue; }
    used.add(key);
    const cc = ctx.cellCentre(cell);
    const rates = Object.assign({ SO2: 0, NOx: 0, CO: 0, PM25: 0 }, q.rates_g_s || {}) as Record<EmitKey, number>;
    for (const k of Object.keys(rates) as EmitKey[]) rates[k] = Math.max(0, +rates[k] || 0);
    s.sources.push({ tag: s.nextTag++, family: fam, sourceId: q.source_id, cell, x: cc.x, y: cc.y, rates, control: { ...(q.control || {}) } });
  }
  if (c.roads) s.roads = { tier1: c.roads.tier1 !== false, tier2: c.roads.tier2 !== false, trafficScale: Math.min(2, Math.max(0, +c.roads.traffic_scale || 0)) };
  if (c.layers) Object.assign(s.layers, c.layers);
  s.section = c.section && c.section.a && c.section.b ? { a: { ...c.section.a }, b: { ...c.section.b }, zTop: c.section.zTop === 600 ? 600 : 2500 } : null;
  s.probe = c.probe ? { x: +c.probe.x, y: +c.probe.y, z: +c.probe.z || 0 } : null;
  s.settings = { allowRotation: !!c.settings?.allowRotation, limitsOnStart: !!c.settings?.limitsOnStart };
  if (s.settings.limitsOnStart) s.layers.limits = true;
  if (!s.settings.allowRotation) s.windFromDeg = null;
  s.linearity = Array.isArray(c.linearity) ? c.linearity.filter((r) => r && typeof r.step === "string") : [];
  s.title = c.title || "";
  s.selected = s.sources.length ? s.sources[0].tag : null;
  return warn;
}

// ------------------------------------------------------------------ link encoding
function b64urlEncode(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function b64urlDecode(s: string): Uint8Array {
  const b = atob(s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4));
  const out = new Uint8Array(b.length);
  for (let i = 0; i < b.length; i++) out[i] = b.charCodeAt(i);
  return out;
}
async function pipe(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const r = new Blob([bytes as BlobPart]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(r).arrayBuffer());
}

/** Encode a configuration for the URL hash: "z" + deflated base64url, or "j" + plain base64url. */
export async function encodeConfig(c: SavedConfig): Promise<string> {
  const raw = new TextEncoder().encode(JSON.stringify(c));
  if (typeof CompressionStream !== "undefined") {
    try { return "z" + b64urlEncode(await pipe(raw, new CompressionStream("deflate-raw"))); } catch { /* fall through */ }
  }
  return "j" + b64urlEncode(raw);
}

export async function decodeConfig(s: string): Promise<SavedConfig> {
  const kind = s[0], body = s.slice(1);
  let bytes = b64urlDecode(body);
  if (kind === "z") bytes = await pipe(bytes, new DecompressionStream("deflate-raw"));
  else if (kind !== "j") throw new Error("Unrecognised configuration link.");
  return JSON.parse(new TextDecoder().decode(bytes)) as SavedConfig;
}
