// Road baselines (C, Phase 3): precomputed ground-level maps per scenario x tier x pollutant on
// the 300 x 300 display grid, log10-u16 encoded, at the observed wind with the hourly traffic
// factor applied. No DOM access.
import { decodeCodes } from "./field";
import type { RoadBaselineBlock, RoadBaselineEntry } from "./manifest";
import type { DisplayGrid } from "./superpose";

/** Emission pollutant of the road maps behind a map pollutant (roads add no SO2). */
export function roadPollutantFor(p: string): string | null {
  return ({ NO2: "NOx", CO: "CO", PM25: "PM25" } as Record<string, string>)[p] ?? null;
}

export function roadEntries(block: RoadBaselineBlock | undefined): RoadBaselineEntry[] {
  if (!block) return [];
  const list = (block.entries || block.maps || (block as { fields?: RoadBaselineEntry[] }).fields || []) as RoadBaselineEntry[];
  return list;
}

const canon = (s: string) => String(s).toUpperCase().replace(/[._\- ]/g, "");

export function findRoadEntry(block: RoadBaselineBlock | undefined, scenarioId: string, tier: number, pollutant: string): RoadBaselineEntry | undefined {
  return roadEntries(block).find((e) => e.scenario_id === scenarioId && Number(e.tier) === tier && canon(e.pollutant) === canon(pollutant));
}

/** True when the block says row 0 of the stored array is the northern edge. */
export function roadRowsFromNorth(block: RoadBaselineBlock | undefined): boolean {
  const o = String(block?.grid?.order ?? block?.order ?? "").toLowerCase();
  return /north|top|flip|descending/.test(o) && !/row 0 (is|=) (the )?south/.test(o);
}

/**
 * Decode one road baseline into the app's grid order (index j * nx + i, j = 0 in the south).
 * `nz` > 1 decodes a vertical companion with the level axis outermost.
 */
export function decodeRoadBaseline(buf: ArrayBuffer, block: RoadBaselineBlock | undefined, entry: RoadBaselineEntry, g: DisplayGrid, nz = 1, log10?: { min: number; step: number }): Float32Array {
  const enc = String(block?.encoding?.name ?? "log10-u16");
  const n = g.nx * g.ny * nz;
  const raw = decodeCodes(buf, enc, n, log10?.min ?? entry.log10_min, log10?.step ?? entry.log10_step, entry.file);
  if (!roadRowsFromNorth(block)) return raw;
  const out = new Float32Array(n);
  for (let l = 0; l < nz; l++) for (let j = 0; j < g.ny; j++) {
    const src = (l * g.ny + (g.ny - 1 - j)) * g.nx, dst = (l * g.ny + j) * g.nx;
    out.set(raw.subarray(src, src + g.nx), dst);
  }
  return out;
}
