/**
 * Fixed colour scale per pollutant (Checkpoint 3a, decision 12): 3 decades in steps of a third of a
 * decade, the same in every hour, starting at a round value in the display unit (data/units.ts:
 * SO2 0.5 ppb, NO2 1 ppb, CO 100 ppb, PM2.5 1 µg/m³). Values below the lowest break stay uncoloured.
 */
export const SCALE_DECADES = 3;
/** Reversed viridis (light to dark): perceptually uniform, colour-blind safe, monotonic in lightness. */
export const RAMP = ["#fde725", "#b5de2b", "#6ece58", "#35b779", "#1f9e89", "#26828e", "#31688e", "#3e4989", "#482878", "#440154"];

/** Breaks (µg/m³) of the ramp from a lower bound in µg/m³, optionally shifted by whole decades. */
export function rampBreaks(loUg: number, offsetDecades = 0): number[] {
  const lo = loUg * Math.pow(10, offsetDecades);
  return RAMP.map((_, i) => lo * Math.pow(10, (i * SCALE_DECADES) / RAMP.length));
}
