// Synchronous engine on the main thread for the linearity module (contract: engine.superpose is
// synchronous). Fields already loaded are used directly; a missing field is fetched with a
// synchronous request (a fallback; `preload` avoids it).
import { superposeFields, type PreparedField } from "../engine";
import type { Manifest } from "../engine/manifest";
import type { Placement } from "../types";
import { FieldStore } from "../worker/store";
import { fieldKey } from "../worker/protocol";

export class MainEngine {
  private store: FieldStore;
  constructor(base: string, private manifest: Manifest) {
    this.store = new FieldStore(base, manifest.grids, manifest.encoding, manifest.fields, 48e6);
  }

  superpose(placements: Placement[], scenarioId: string, xq: Float64Array, yq: Float64Array, zq: Float64Array): Float64Array {
    const sc = this.manifest.scenarios[scenarioId];
    if (!sc) throw new Error(`unknown scenario ${scenarioId}`);
    const fields = new Map<string, PreparedField>();
    for (const p of placements) if (!fields.has(p.source_id)) fields.set(p.source_id, this.store.getSync(fieldKey(p.source_id, scenarioId)));
    return superposeFields(placements, fields, sc.wd_deg, xq, yq, zq, 0);
  }

  async preload(sourceIds: string[], scenarioId: string): Promise<void> {
    await Promise.all([...new Set(sourceIds)].map((s) => this.store.get(fieldKey(s, scenarioId))));
  }
}
