// Road baselines on the main thread: ground maps (300 x 300, 100 m) per hour x tier x pollutant,
// and the optional vertical companion (150 x 150 cells of 200 m, 10 heights to 500 m).
import { decodeRoadBaseline, findRoadEntry } from "../engine/roads";
import type { RoadBaselineBlock } from "../engine/manifest";
import type { DisplayGrid } from "../engine/superpose";

export interface VerticalMap { data: Float32Array; nx: number; ny: number; x0: number; y0: number; d: number; z: number[] }

export class RoadMaps {
  private ground = new Map<string, Promise<Float32Array | null>>();
  private vert = new Map<string, Promise<VerticalMap | null>>();
  readonly groundReady = new Map<string, Float32Array>();
  readonly vertReady = new Map<string, VerticalMap>();
  constructor(private base: string, private block: RoadBaselineBlock | null, private grid: DisplayGrid) {}

  get available(): boolean { return !!this.block; }
  get verticalAvailable(): boolean { return !!this.block?.vertical; }

  static key(scn: string, tier: number, pol: string) { return `${scn}|${tier}|${pol}`; }

  loadGround(scn: string, tier: number, pol: string): Promise<Float32Array | null> {
    const k = RoadMaps.key(scn, tier, pol);
    let p = this.ground.get(k);
    if (!p) {
      const e = findRoadEntry(this.block ?? undefined, scn, tier, pol);
      p = !e ? Promise.resolve(null) : fetch(this.base + "fields/" + e.file).then(async (r) => {
        if (!r.ok) throw new Error(`${e.file}: HTTP ${r.status}`);
        const m = decodeRoadBaseline(await r.arrayBuffer(), this.block!, e, this.grid);
        this.groundReady.set(k, m);
        return m;
      }).catch((err) => { console.warn(err); return null; });
      this.ground.set(k, p);
    }
    return p;
  }

  loadVertical(scn: string, tier: number, pol: string): Promise<VerticalMap | null> {
    const k = RoadMaps.key(scn, tier, pol);
    let p = this.vert.get(k);
    if (!p) {
      const e = findRoadEntry(this.block ?? undefined, scn, tier, pol) as (ReturnType<typeof findRoadEntry> & { vertical?: { file: string; log10_min: number; log10_step: number } }) | undefined;
      const v = this.block?.vertical as { nx: number; ny: number; xmin: number; ymin: number; dx_m: number; z_m: number[] } | undefined;
      p = !e?.vertical || !v ? Promise.resolve(null) : fetch(this.base + "fields/" + e.vertical.file).then(async (r) => {
        if (!r.ok) throw new Error(`${e.vertical!.file}: HTTP ${r.status}`);
        const g: DisplayGrid = { nx: v.nx, ny: v.ny, x0: v.xmin, y0: v.ymin, d: v.dx_m };
        const data = decodeRoadBaseline(await r.arrayBuffer(), { ...this.block!, grid: { ...v, order: (this.block!.vertical as { order?: string }).order } } as RoadBaselineBlock,
          { ...e, file: e.vertical!.file }, g, v.z_m.length, { min: e.vertical!.log10_min, step: e.vertical!.log10_step });
        const vm: VerticalMap = { data, nx: v.nx, ny: v.ny, x0: v.xmin, y0: v.ymin, d: v.dx_m, z: v.z_m };
        this.vertReady.set(k, vm);
        return vm;
      }).catch((err) => { console.warn(err); return null; });
      this.vert.set(k, p);
    }
    return p;
  }
}

/** Ground value of a road map in the display cell that contains (x, y). */
export function cellValue(map: Float32Array, g: DisplayGrid, x: number, y: number): number {
  const i = Math.floor((x - g.x0) / g.d), j = Math.floor((y - g.y0) / g.d);
  if (i < 0 || j < 0 || i >= g.nx || j >= g.ny) return 0;
  return map[j * g.nx + i];
}

/**
 * Vertical companion at (x, y, z): bilinear between 200 m cell centres, linear between its heights,
 * null above its top level (not computed there).
 */
export function verticalValue(v: VerticalMap, x: number, y: number, z: number): number | null {
  const zt = v.z[v.z.length - 1];
  if (z > zt + 1e-6) return null;
  let k = 0;
  while (k < v.z.length - 2 && z > v.z[k + 1]) k++;
  const tz = Math.min(1, Math.max(0, (z - v.z[k]) / (v.z[k + 1] - v.z[k])));
  const fx = (x - v.x0) / v.d - 0.5, fy = (y - v.y0) / v.d - 0.5;
  const i0 = Math.max(0, Math.min(v.nx - 2, Math.floor(fx))), j0 = Math.max(0, Math.min(v.ny - 2, Math.floor(fy)));
  const tx = Math.min(1, Math.max(0, fx - i0)), ty = Math.min(1, Math.max(0, fy - j0));
  const at = (kk: number) => {
    const b = kk * v.nx * v.ny;
    const a00 = v.data[b + j0 * v.nx + i0], a10 = v.data[b + j0 * v.nx + i0 + 1];
    const a01 = v.data[b + (j0 + 1) * v.nx + i0], a11 = v.data[b + (j0 + 1) * v.nx + i0 + 1];
    return (1 - ty) * ((1 - tx) * a00 + tx * a10) + ty * ((1 - tx) * a01 + tx * a11);
  };
  return (1 - tz) * at(k) + tz * at(k + 1);
}
