// Control cost (Checkpoint 3a, decision 6): annualised capital (plus fixed O&M as a fraction of
// capital) and a variable cost per tonne removed, from controls.json (A's controls.yaml).
//   capital  C = usd_per_unit x S_ref x (S / S_ref) ^ exponent   (S: the source's capacity in the basis)
//   annual   C x (CRF + fixed_om_fraction) + variable_usd_per_ton x tonnes removed
import { T_PER_YR_PER_G_S } from "./catalogue";
import type { Controls, Tech } from "./model";

export interface CostBreakdown {
  tonsRemoved: number;      // t/yr (continuous operation at the hour's rate)
  capitalUsd: number;       // installed capital
  annualFixedUsd: number;   // capital x (CRF + fixed O&M fraction)
  annualVariableUsd: number;
  annualUsd: number;
  usdPerTon: number | null; // annual cost per tonne removed
}

export const NO_COST: CostBreakdown = { tonsRemoved: 0, capitalUsd: 0, annualFixedUsd: 0, annualVariableUsd: 0, annualUsd: 0, usdPerTon: null };

export function capitalUsd(tech: Tech, familyKey: string, sourceId: string, controls: Controls): number {
  const c = tech.capital[familyKey];
  if (!c) return 0;
  const size = controls.capacity[sourceId]?.[c.basis] ?? c.refSize;
  return c.usdPerUnit * c.refSize * Math.pow(size / c.refSize, c.exponent);
}

export function techCost(tech: Tech | null, familyKey: string, sourceId: string, rateGs: number, controls: Controls): CostBreakdown {
  if (!tech || tech.efficiency <= 0) return NO_COST;
  const tons = rateGs * tech.efficiency * T_PER_YR_PER_G_S;
  const cap = capitalUsd(tech, familyKey, sourceId, controls);
  const fixed = cap * ((tech.crf ?? 0) + tech.fixedOmFraction);
  const variable = tech.variableUsdPerTon * tons;
  const annual = fixed + variable;
  return { tonsRemoved: tons, capitalUsd: cap, annualFixedUsd: fixed, annualVariableUsd: variable, annualUsd: annual, usdPerTon: tons > 0 ? annual / tons : null };
}

export function addCosts(a: CostBreakdown, b: CostBreakdown): CostBreakdown {
  const tons = a.tonsRemoved + b.tonsRemoved, annual = a.annualUsd + b.annualUsd;
  return { tonsRemoved: tons, capitalUsd: a.capitalUsd + b.capitalUsd, annualFixedUsd: a.annualFixedUsd + b.annualFixedUsd,
    annualVariableUsd: a.annualVariableUsd + b.annualVariableUsd, annualUsd: annual, usdPerTon: tons > 0 ? annual / tons : null };
}
